class MagnetProtocolError(RuntimeError):
    pass
class MagnetAsciiSerialDevice:
    def __init__(self, port: str, label: str, logger: Callable[[str], None]) -> None:
        self.port = port
        self.label = label
        self.logger = logger
        self.handle = None
        self.lock = threading.RLock()
    @property
    def connected(self) -> bool:
        return bool(self.handle is not None and self.handle.is_open)
    def _log(self, text: str) -> None:
        self.logger(f"{self.label}: {text}")
    def connect(self) -> None:
        if serial is None:
            raise RuntimeError("pyserial is missing; please run: py -m pip install pyserial")
        with self.lock:
            self.close()
            self.handle = serial.Serial(
                port=self.port,
                baudrate=MAGNET_BAUD_RATE,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=MAGNET_READ_TIMEOUT_S,
                write_timeout=MAGNET_WRITE_TIMEOUT_S,
                xonxoff=False,
                rtscts=False,
                dsrdtr=False,
            )
            self.handle.reset_input_buffer()
            self.handle.reset_output_buffer()
            self._log(f"Opened {self.port} (115200 / 8N1)")
    def close(self) -> None:
        with self.lock:
            handle = self.handle
            self.handle = None
            if handle is not None:
                try:
                    if handle.is_open:
                        handle.close()
                finally:
                    self._log(f"Closed {self.port}")
    def _require_open(self):
        if not self.connected:
            raise RuntimeError(f"{self.label} is not connected")
        return self.handle
    @staticmethod
    def _decode(raw: bytes) -> str:
        return raw.decode("ascii", errors="replace").strip("\x00\r\n ")
    def exchange(self, command: str, matcher: Callable[[str], object | None] | None=None, deadline_s: float=MAGNET_REPLY_DEADLINE_S, attempts: int=1):
        wire = command.rstrip("\r\n").encode("ascii") + b"\r"
        with self.lock:
            handle = self._require_open()
            all_received: list[str] = []
            attempts = max(1, int(attempts))
            for attempt in range(1, attempts + 1):
                if attempt > 1:
                    self._log(f"Attempt {attempt}/{attempts} of {command!r}")
                    time.sleep(MAGNET_RETRY_DELAY_S)
                if attempt == 1:
                    handle.reset_input_buffer()
                handle.write(wire)
                handle.flush()
                self._log(f"TX {wire!r}")
                if matcher is None:
                    self._drain_quiet(handle)
                    return None
                result, received = self._read_matching_reply(handle, matcher, deadline_s)
                all_received.extend(received)
                if result is not None:
                    return result
            summary = " | ".join(all_received) if all_received else "<no response>"
            raise MagnetProtocolError(f'{self.label} did not return the expected data in {attempts} consecutive attempts; received: {summary}')
    def _read_matching_reply(self, handle, matcher: Callable[[str], object | None], deadline_s: float) -> tuple[object | None, list[str]]:
        deadline = time.monotonic() + deadline_s
        pending = bytearray()
        received: list[str] = []
        def consume(raw: bytes):
            text = self._decode(raw)
            if not text:
                return None
            received.append(text)
            self._log(f"RX {raw!r}")
            return matcher(text)
        while time.monotonic() < deadline:
            waiting = int(getattr(handle, "in_waiting", 0) or 0)
            chunk = handle.read(waiting if waiting > 0 else 1)
            if not chunk:
                continue
            pending.extend(chunk)
            while True:
                delimiter_indexes = [index for index in (pending.find(b'\r'), pending.find(b'\n')) if index >= 0]
                if not delimiter_indexes:
                    break
                index = min(delimiter_indexes)
                raw = bytes(pending[:index])
                del pending[: index + 1]
                result = consume(raw)
                if result is not None:
                    return result, received
            if pending:
                text = self._decode(bytes(pending))
                result = matcher(text) if text else None
                if result is not None:
                    received.append(text)
                    self._log(f"RX {bytes(pending)!r}")
                    return result, received
        if pending:
            consume(bytes(pending))
        return None, received
    def _drain_quiet(self, handle) -> None:
        end = time.monotonic() + MAGNET_QUIET_TIME_S
        while time.monotonic() < end:
            if handle.in_waiting <= 0:
                time.sleep(0.005)
                continue
            raw = handle.read_until(b"\n")
            if raw:
                text = self._decode(raw)
                if text:
                    self._log(f"RX {raw!r}")
                end = time.monotonic() + MAGNET_QUIET_TIME_S
class MagnetKepcoBOP(MagnetAsciiSerialDevice):
    def __init__(self, port: str, label: str, logger: Callable[[str], None]) -> None:
        super().__init__(port, label, logger)
        self.output_armed = False
    def connect(self) -> None:
        super().connect()
        self.output_armed = False
    def close(self) -> None:
        self.output_armed = False
        super().close()
    @staticmethod
    def _parse_current(line: str) -> float | None:
        cleaned = MAGNET_CHECKSUM_RE.sub("", line)
        match = MAGNET_CURRENT_RE.search(cleaned)
        return float(match.group(1)) if match else None
    def set_current(self, amperes: float) -> None:
        value = float(amperes)
        if not math.isfinite(value):
            raise ValueError("Magnet current must be a finite value")
        if abs(value) > MAGNET_CURRENT_LIMIT_A + 1e-12:
            raise ValueError(f'Current {value:g} A exceeds the software limit ±{MAGNET_CURRENT_LIMIT_A:g} A')
        if value != 0.0 and not self.output_armed:
            raise RuntimeError(f'{self.label} is not enabled; please click "Enable/Zero" first')
        self.exchange(f"T {value:.3f}")
    def query_current(self) -> float:
        return float(self.exchange('IQ', self._parse_current, attempts=MAGNET_QUERY_ATTEMPTS))
    def prepare_remote(self) -> None:
        self.output_armed = False
        self.exchange("remote")
        time.sleep(MAGNET_REMOTE_SETTLE_S)
    def initialize_at_zero(self) -> float:
        self.output_armed = False
        self.prepare_remote()
        self.set_current(0.0)
        self.exchange("en")
        self.output_armed = True
        self.set_current(0.0)
        time.sleep(MAGNET_COMMAND_SETTLE_S)
        return self.query_current()
class MagnetGaussMeter(MagnetAsciiSerialDevice):
    @staticmethod
    def _parse_field(line: str) -> float | None:
        match = MAGNET_FIELD_RE.search(line)
        return float(match.group(1)) if match else None
    def query_field(self) -> float:
        return float(self.exchange('GS', self._parse_field, attempts=MAGNET_QUERY_ATTEMPTS))
@dataclass
class MagnetChannel:
    key: str
    bop: MagnetKepcoBOP | None = None
    gauss: MagnetGaussMeter | None = None
    def close(self) -> None:
        if self.bop is not None:
            self.bop.close()
        if self.gauss is not None:
            self.gauss.close()
        self.bop = None
        self.gauss = None
class K10CR1KinesisController:
    def __init__(self, logger: Callable[[str], None]) -> None:
        self.logger = logger
        self.device = None
        self.configuration = None
        self.serial_no = K10CR1_DEFAULT_SERIAL
        self._connection_lock = threading.RLock()
        self._api_loaded = False
        self._DeviceManagerCLI = None
        self._DeviceConfiguration = None
        self._CageRotator = None
        self._Decimal = None
        self._Convert = None
        self._MotorDirection = None
    @property
    def connected(self) -> bool:
        return self.device is not None
    def _log(self, text: str) -> None:
        self.logger(f"Rotation stage: {text}")
    @staticmethod
    def _kinesis_directory() -> Path:
        for directory in K10CR1_KINESIS_DIRECTORIES:
            if all((directory / dll).is_file() for dll in K10CR1_REQUIRED_DLLS):
                return directory
        checked = "\n".join(str(path) for path in K10CR1_KINESIS_DIRECTORIES)
        raise RuntimeError(f'No complete Thorlabs Kinesis installation was found. Checked:\n{checked}\nPlease install a Kinesis matching the Python bitness.')
    def _load_api(self) -> None:
        if self._api_loaded:
            return
        if sys.platform != "win32":
            raise RuntimeError("Thorlabs Kinesis control can only run on Windows with Kinesis installed")
        directory = self._kinesis_directory()
        try:
            import clr
        except ImportError as error:
            raise RuntimeError('pythonnet is missing; please run on the control PC: py -m pip install pythonnet') from error
        try:
            for filename in K10CR1_REQUIRED_DLLS:
                clr.AddReference(str(directory / filename))
            from System import Convert, Decimal
            from Thorlabs.MotionControl.DeviceManagerCLI import DeviceConfiguration, DeviceManagerCLI
            from Thorlabs.MotionControl.GenericMotorCLI import MotorDirection
            from Thorlabs.MotionControl.IntegratedStepperMotorsCLI import CageRotator
        except BaseException as error:
            raise RuntimeError(f"Kinesis DLL load failed: {error}") from error
        self._Decimal = Decimal
        self._DeviceManagerCLI = DeviceManagerCLI
        self._DeviceConfiguration = DeviceConfiguration
        self._CageRotator = CageRotator
        self._api_loaded = True
        self._Convert = Convert
        self._MotorDirection = MotorDirection
        self._log(f"Loaded Kinesis: {directory}")
    @staticmethod
    def _flag(status, name: str) -> bool:
        try:
            return bool(getattr(status, name))
        except BaseException:
            return False
    @staticmethod
    def _text(value) -> str:
        try:
            return str(value)
        except BaseException:
            return ""
    def _require_device(self):
        if self.device is None:
            raise RuntimeError("K10CR1 rotation stage is not connected")
        return self.device
    def connect(self, serial_no: str) -> dict[str, object]:
        serial_no = serial_no.strip()
        if not serial_no.isdigit():
            raise ValueError("Rotation stage S/N must contain digits only")
        with self._connection_lock:
            if self.device is not None:
                if serial_no == self.serial_no:
                    return self.read_state()
                self.disconnect()
            self._load_api()
            self._DeviceManagerCLI.BuildDeviceList()
            devices = [str(item) for item in self._DeviceManagerCLI.GetDeviceList()]
            if serial_no not in devices:
                shown = ", ".join(devices) if devices else "no Kinesis devices found"
                raise RuntimeError(f"S/N {serial_no} not found; device list: {shown}")
            device = self._CageRotator.CreateCageRotator(serial_no)
            if device is None:
                raise RuntimeError(f"Kinesis cannot create a CageRotator for S/N {serial_no}")
            self.device = device
            self.serial_no = serial_no
            polling_started = False
            try:
                device.Connect(serial_no)
                if not bool(device.IsSettingsInitialized()):
                    device.WaitForSettingsInitialized(15_000)
                if not bool(device.IsSettingsInitialized()):
                    raise TimeoutError("Timed out waiting for K10CR1 settings initialization")
                device.StartPolling(250)
                polling_started = True
                time.sleep(0.5)
                device.EnableDevice()
                time.sleep(1.0)
                self.configuration = device.LoadMotorConfiguration(serial_no, self._DeviceConfiguration.DeviceSettingsUseOptionType.UseFileSettings)
                if self.configuration is None:
                    raise RuntimeError("LoadMotorConfiguration returned an empty configuration")
                settings_name = self._text(getattr(self.configuration, 'DeviceSettingsName', ''))
                description = self._text(getattr(device.GetDeviceInfo(), "Description", ""))
                identity = f"{description} {settings_name}".lower()
                if "k10cr" not in identity and "rotation" not in identity:
                    raise RuntimeError(f'The loaded device settings do not look like a K10CR1; motion refused: Description={description!r}, Settings={settings_name!r}')
                self._log(f"Connected S/N {serial_no}; {description or 'K10CR1'}; settings {settings_name or 'loaded'}")
                return self.read_state()
            except BaseException as error:
                try:
                    if polling_started:
                        device.StopPolling()
                except BaseException:
                    pass
                try:
                    device.Disconnect()
                except BaseException:
                    pass
                self.device = None
                self.configuration = None
                raise RuntimeError(
                    "K10CR1 connection or initialization failed. Please confirm USB/power are normal and close "
                    f"the official Thorlabs Kinesis GUI first. Original error: {error}"
                ) from error
    def disconnect(self) -> None:
        with self._connection_lock:
            device = self.device
            self.device = None
            self.configuration = None
            if device is None:
                return
            try:
                status = device.Status
                if self._flag(status, 'IsMoving') or self._flag(status, 'IsHoming') or self._flag(status, 'IsJogging'):
                    device.StopImmediate()
                    time.sleep(0.1)
            except BaseException:
                pass
            try:
                device.StopPolling()
            except BaseException:
                pass
            try:
                device.Disconnect()
            finally:
                self._log(f"Disconnected S/N {self.serial_no}")
    def read_state(self) -> dict[str, object]:
        device = self._require_device()
        try:
            device.RequestStatus()
            time.sleep(0.1)
        except BaseException:
            pass
        status = device.Status
        info = device.GetDeviceInfo()
        return {
            "serial": self.serial_no,
            "description": self._text(getattr(info, "Description", "K10CR1")),
            "settings": self._text(
                getattr(self.configuration, "DeviceSettingsName", "")
            ),
            "position": float(self._Convert.ToDouble(device.Position)),
            "homed": self._flag(status, "IsHomed"),
            "homing": self._flag(status, "IsHoming"),
            "moving": self._flag(status, "IsMoving"),
            "jogging": self._flag(status, "IsJogging"),
            "enabled": self._flag(status, "IsEnabled"),
            "error": self._flag(status, "IsError"),
            "forward_limit": self._flag(status, "ForwardLimit"),
            "reverse_limit": self._flag(status, "ReverseLimit"),
        }
    def _run_motion(self, name: str, operation: Callable[[], None]) -> dict[str, object]:
        device = self._require_device()
        try:
            operation()
            state = self.read_state()
            self._log(f"{name} complete; position {float(state['position']):.6f}°")
            return state
        except BaseException as error:
            try:
                device.StopImmediate()
            except BaseException:
                pass
            raise RuntimeError(f"{name} failed: {error}") from error
    def home(self, timeout_ms: int = 120_000) -> dict[str, object]:
        device = self._require_device()
        state = self.read_state()
        if bool(state["forward_limit"]) and bool(state["reverse_limit"]):
            raise RuntimeError("Both forward and reverse limits are triggered; Home refused, please check the sensors or Kinesis configuration")
        self._log("Starting Home; the rotation stage may perform a large-angle motion")
        state = self._run_motion("Home", lambda: device.Home(int(timeout_ms)))
        time.sleep(0.25)
        state = self.read_state()
        if not bool(state["homed"]):
            raise RuntimeError("IsHomed is still False after the Home command returned")
        return state
    def _move_relative_impl(self, angle_deg: float, timeout_ms: int, require_homed: bool) -> dict[str, object]:
        state = self.read_state()
        if require_homed and not bool(state["homed"]):
            raise RuntimeError("Device is not homed; relative motion is disabled. Please Home first or only use the ±1° diagnostic nudge")
        angle = float(angle_deg)
        if not math.isfinite(angle) or abs(angle) > 360.0:
            raise ValueError("Relative angle must be within -360° to +360°")
        if abs(angle) < 1e-12:
            self._log("Relative angle is 0; no motion command sent")
            return state
        direction = self._MotorDirection.Forward if angle > 0.0 else self._MotorDirection.Backward
        device = self._require_device()
        return self._run_motion(f'Relative move {angle:+g}°', lambda: device.MoveRelative(direction, self._Decimal(float(abs(angle))), int(timeout_ms)))
    def move_relative(self, angle_deg: float, timeout_ms: int = 120_000) -> dict[str, object]:
        return self._move_relative_impl(angle_deg, timeout_ms, require_homed=True)
    def move_absolute(self, angle_deg: float, timeout_ms: int = 120_000) -> dict[str, object]:
        state = self.read_state()
        if not bool(state["homed"]):
            raise RuntimeError("Device is not homed; absolute motion is disabled")
        angle = float(angle_deg)
        if not math.isfinite(angle) or angle < 0.0 or angle > 360.0:
            raise ValueError("Absolute angle must be within 0° to 360°")
        device = self._require_device()
        return self._run_motion(f'Move to {angle:g}°', lambda: device.MoveTo(self._Decimal(float(angle)), int(timeout_ms)))
    def diagnostic_nudge(self, angle_deg: float, timeout_ms: int = 30_000) -> dict[str, object]:
        angle = float(angle_deg)
        if not math.isfinite(angle) or angle == 0.0 or abs(angle) > 1.0:
            raise ValueError("Diagnostic nudge must be non-zero and not exceed ±1°")
        return self._move_relative_impl(angle, timeout_ms, require_homed=False)
    def identify(self) -> None:
        self._require_device().IdentifyDevice()
        self._log("Device identify command sent")
    def stop(self) -> dict[str, object]:
        device = self._require_device()
        try:
            device.StopImmediate()
        except BaseException as first_error:
            try:
                device.Stop(5_000)
            except BaseException as second_error:
                raise RuntimeError(f'StopImmediate failed: {first_error}; Stop also failed: {second_error}') from second_error
        time.sleep(0.1)
        self._log("Immediate stop sent")
        return self.read_state()
class LEDProtocolError(RuntimeError):
    pass
@dataclass
class ChannelSettings:
    current: int = 0
    mode: int = 0
    p: int = 5
    g: int = 0
    d: int = 5
    f: int = 0
    def values(self) -> dict[str, int]:
        return {'i': self.current, 'm': self.mode, 'p': self.p, 'g': self.g, 'd': self.d, 'f': self.f}
class LEDSerialController:
    def __init__(self, logger: Callable[[str], None]) -> None:
        self._serial = None
        self._lock = threading.RLock()
        self._logger = logger
    @property
    def is_connected(self) -> bool:
        return self._serial is not None and self._serial.is_open
    @property
    def port(self) -> str | None:
        return None if self._serial is None else self._serial.port
    def connect(self, port: str) -> None:
        if serial is None:
            raise RuntimeError("pyserial is missing: py -m pip install pyserial")
        port = port.strip()
        if not port:
            raise ValueError("Serial port name cannot be empty")
        with self._lock:
            self.disconnect()
            connection = serial.Serial()
            connection.port = port
            connection.baudrate = BAUD_RATE
            connection.bytesize = serial.EIGHTBITS
            connection.parity = serial.PARITY_NONE
            connection.stopbits = serial.STOPBITS_ONE
            connection.timeout = READ_TIMEOUT_S
            connection.write_timeout = WRITE_TIMEOUT_S
            connection.xonxoff = False
            connection.rtscts = False
            connection.dsrdtr = False
            connection.dtr = False
            connection.rts = False
            try:
                connection.open()
                connection.reset_input_buffer()
                connection.reset_output_buffer()
            except BaseException:
                if connection.is_open:
                    connection.close()
                raise
            self._serial = connection
        self._logger(f"Connected {port}: {BAUD_RATE}, 8-N-1")
    def disconnect(self) -> None:
        with self._lock:
            connection = self._serial
            self._serial = None
            if connection is not None and connection.is_open:
                port = connection.port
                connection.close()
                self._logger(f"Disconnected {port}")
    def _connection(self):
        if not self.is_connected:
            raise RuntimeError("LED controller is not connected")
        return self._serial
    @staticmethod
    def _command(parameter: str, channel: int, value: int | str) -> str:
        command = f"{parameter}{channel}={value}"
        if COMMAND_RE.fullmatch(command) is None:
            raise ValueError(f"Illegal LED command: {command!r}")
        return command
    def _write_locked(self, command: str) -> None:
        connection = self._connection()
        payload = (command + "\r").encode("ascii")
        connection.write(payload)
        connection.flush()
        self._logger(f"TX  {command}\\r")
        time.sleep(COMMAND_DELAY_S)
    def query_parameter(self, parameter: str, channel: int) -> int:
        expected = f"{parameter}{channel}"
        with self._lock:
            connection = self._connection()
            connection.reset_input_buffer()
            self._write_locked(self._command(parameter, channel, "?"))
            response_bytes = connection.read_until(b"\n")
        if not response_bytes:
            raise TimeoutError(f"Query {expected} timed out")
        try:
            response = response_bytes.decode("ascii").strip("\r\n")
        except UnicodeDecodeError as error:
            raise LEDProtocolError(f"Received non-ASCII data: {response_bytes!r}") from error
        self._logger(f"RX  {response_bytes!r}")
        match = RESPONSE_RE.fullmatch(response)
        if match is None:
            raise LEDProtocolError(f"Unrecognized response: {response!r}")
        returned = f"{match.group(1)}{match.group(2)}"
        if returned != expected:
            raise LEDProtocolError(f"Queried {expected}, controller returned {returned}")
        return int(match.group(3))
    def query_channel(self, channel: int) -> ChannelSettings:
        values = {parameter: self.query_parameter(parameter, channel) for parameter in PARAMETERS}
        return ChannelSettings(current=values['i'], mode=values['m'], p=values['p'], g=values['g'], d=values['d'], f=values['f'])
    def query_all(self) -> dict[int, ChannelSettings]:
        return {channel: self.query_channel(channel) for channel in CHANNELS}
    def apply_channel(self, channel: int, settings: ChannelSettings) -> None:
        with self._lock:
            for parameter, value in settings.values().items():
                self._write_locked(self._command(parameter, channel, value))
    def apply_all(self, settings: dict[int, ChannelSettings]) -> None:
        with self._lock:
            for channel in CHANNELS:
                for parameter, value in settings[channel].values().items():
                    self._write_locked(self._command(parameter, channel, value))
    def all_off(self) -> None:
        with self._lock:
            for channel in CHANNELS:
                self._write_locked(self._command("i", channel, 0))
            for channel in CHANNELS:
                self._write_locked(self._command("m", channel, 0))
@dataclass
class CameraFrame:
    raw: object
    preview: object
    difference: object
    display_difference: object
    exposure_ms: float
    raw_mean: float
    raw_max: int
    contrast_auto: bool
    background_enabled: bool
    background_mode: str
    drift_dx: float
    drift_dy: float
    drift_response: float
    temporal_average_count: int
    spatial_binning: int
    mean_filter_size: int
    window_start_monotonic: float = math.nan
    exposure_start_monotonic: float = math.nan
    background_serial: int = 0
    background_raw: object = None
_BACKGROUND_SERIAL_LOCK = threading.Lock()
_BACKGROUND_SERIAL = [0]
def next_background_serial() -> int:
    with _BACKGROUND_SERIAL_LOCK:
        _BACKGROUND_SERIAL[0] += 1
        return _BACKGROUND_SERIAL[0]
CAMERA_EXPOSURE_START_MARGIN_S = 0.05
CAMERA_STOP_JOIN_S = 3.0
CAMERA_WAIT_SLICE_S = 1.0
CAMERA_RELEASE_POLL_MS = 500
class CameraVideoRecorder:
    def __init__(self, path: Path, fps: float, width: int, height: int) -> None:
        if cv2 is None or np is None:
            raise RuntimeError('Video recording requires OpenCV; install with: py -m pip install opencv-python')
        self.path = Path(path)
        self.fps = float(fps)
        self.width = max(2, int(width) // 2 * 2)
        self.height = max(2, int(height) // 2 * 2)
        self.frame_queue: queue.Queue[object] = queue.Queue(maxsize=16)
        self.stats_lock = threading.Lock()
        self.frames_written = 0
        self.frames_dropped = 0
        self.start_monotonic = time.monotonic()
        self.next_frame_monotonic = self.start_monotonic
        self.accepting = True
        self.writer = None
        self.codec = ""
        self.is_color = True
        self.error: BaseException | None = None
        self.path.parent.mkdir(parents=True, exist_ok=True)
        for codec in ("MJPG", "I420", "WMV2", "XVID"):
            candidate = cv2.VideoWriter(str(self.path), cv2.VideoWriter_fourcc(*codec), self.fps, (self.width, self.height), True)
            if candidate.isOpened():
                self.writer = candidate
                self.codec = codec
                break
            candidate.release()
        if self.writer is None:
            raise RuntimeError('Cannot create a Windows-compatible AVI recording; none of the MJPG/I420/WMV2/XVID encoders is available')
        self.thread = threading.Thread(target=self._writer_loop, name='camera-video-writer', daemon=True)
        self.thread.start()
    def reserve_frame_slot(self) -> bool:
        if not self.accepting or self.error is not None:
            return False
        now = time.monotonic()
        if now + 1e-9 < self.next_frame_monotonic:
            return False
        period = 1.0 / self.fps
        self.next_frame_monotonic += period
        if self.next_frame_monotonic <= now:
            self.next_frame_monotonic = now + period
        return True
    def enqueue(self, frame) -> None:
        if not self.accepting:
            return
        array = np.asarray(frame, dtype=np.uint8)
        if array.ndim != 2:
            raise ValueError("Recording frames must be 2-D 8-bit grayscale images")
        if array.shape != (self.height, self.width):
            array = cv2.resize(array, (self.width, self.height), interpolation=cv2.INTER_AREA)
        else:
            array = array.copy()
        try:
            self.frame_queue.put_nowait(array)
        except queue.Full:
            try:
                self.frame_queue.get_nowait()
            except queue.Empty:
                pass
            with self.stats_lock:
                self.frames_dropped += 1
            try:
                self.frame_queue.put_nowait(array)
            except queue.Full:
                with self.stats_lock:
                    self.frames_dropped += 1
    def _writer_loop(self) -> None:
        try:
            while True:
                frame = self.frame_queue.get()
                if frame is None:
                    break
                compatible_frame = np.repeat(frame[:, :, None], 3, axis=2)
                self.writer.write(compatible_frame)
                with self.stats_lock:
                    self.frames_written += 1
        except BaseException as error:
            self.error = error
        finally:
            try:
                self.writer.release()
            except BaseException:
                pass
    def stop(self) -> dict[str, object]:
        if self.accepting:
            self.accepting = False
            while True:
                try:
                    self.frame_queue.put_nowait(None)
                    break
                except queue.Full:
                    try:
                        self.frame_queue.get_nowait()
                    except queue.Empty:
                        break
                    with self.stats_lock:
                        self.frames_dropped += 1
        self.thread.join(timeout=8.0)
        if self.thread.is_alive():
            raise TimeoutError("Finalising the video file took more than 8 s; do not shut down the PC immediately")
        if self.error is not None:
            raise RuntimeError(f"Video write failed: {self.error}")
        return self.snapshot()
    def snapshot(self) -> dict[str, object]:
        with self.stats_lock:
            written = int(self.frames_written)
            dropped = int(self.frames_dropped)
        return {
            "path": self.path,
            "fps": self.fps,
            "codec": self.codec,
            "pixel_layout": "BGR-compatible grayscale",
            "width": self.width,
            "height": self.height,
            "frames": written,
            "dropped": dropped,
            "elapsed_s": max(0.0, time.monotonic() - self.start_monotonic),
        }
class CameraAcquisitionWorker:
    def __init__(self, logger: Callable[[str], None]) -> None:
        self.logger = logger
        self.frames: queue.Queue[CameraFrame] = queue.Queue(maxsize=1)
        self.errors: queue.Queue[BaseException] = queue.Queue(maxsize=1)
        self.stop_event = threading.Event()
        self.settings_lock = threading.Lock()
        self.contrast_auto = False
        self.fixed_low = 0.0
        self.fixed_high = 65535.0
        self.last_low = 0.0
        self.last_high = 65535.0
        self.fixed_difference_max_abs = 1.0
        self.fixed_difference_center = 0.0
        self.last_difference_max_abs = 1.0
        self.last_difference_center = 0.0
        self.difference_contrast_valid = False
        self.difference_manual_clim: tuple[float, float] | None = None
        self.difference_temporal_average_count = DIFFERENCE_TEMPORAL_AVERAGE_FRAMES
        self.difference_spatial_binning = DIFFERENCE_SPATIAL_BINNING
        self.difference_mean_filter_size = DIFFERENCE_MEAN_FILTER_SIZE
        self.difference_average_reset_requested = True
        self._difference_average_sum = None
        self._difference_average_samples = 0
        self._difference_average_previous = None
        self.requested_exposure_s = EXPOSURE_S
        self.active_exposure_s = EXPOSURE_S
        self.exposure_update_requested = False
        self.background_mode = "off"
        self.last_background_mode = "tracking"
        self.background_enabled = False
        self.background_capture_requested = False
        self.background = None
        self.background_serial = 0
        self._background_prepared: DriftBackground | None = None
        self.thread = threading.Thread(target=self._run, name='pco-camera', daemon=True)
    def start(self) -> None:
        self.thread.start()
    def stop(self) -> bool:
        self.stop_event.set()
        if self.thread.is_alive():
            self.thread.join(timeout=CAMERA_STOP_JOIN_S)
        return not self.releasing
    @property
    def releasing(self) -> bool:
        return self.thread.ident is not None and self.thread.is_alive()
    def _wait_for_new_image(self, camera) -> bool:
        supported = self.__dict__.get("_wait_timeout_supported")
        if supported is None:
            import inspect
            try:
                supported = "timeout" in inspect.signature(camera.wait_for_new_image).parameters
            except (TypeError, ValueError):
                supported = False
            self._wait_timeout_supported = supported
        if not supported:
            camera.wait_for_new_image()
            return True
        try:
            camera.wait_for_new_image(timeout=CAMERA_WAIT_SLICE_S)
        except Exception as error:
            if isinstance(error, TimeoutError) or "timeout" in type(error).__name__.lower():
                return False
            raise
        return True
    def toggle_contrast(self) -> bool:
        with self.settings_lock:
            if self.difference_manual_clim is not None:
                self.difference_manual_clim = None
                self.contrast_auto = True
                self.difference_contrast_valid = False
                return True
            if self.contrast_auto:
                self.fixed_low = self.last_low
                self.fixed_high = self.last_high
                if self.difference_contrast_valid:
                    self.fixed_difference_max_abs = self.last_difference_max_abs
                    self.fixed_difference_center = self.last_difference_center
                self.contrast_auto = False
            else:
                self.contrast_auto = True
                self.difference_contrast_valid = False
            return self.contrast_auto
    def update_auto_contrast_bounds(self, low: float, high: float) -> None:
        with self.settings_lock:
            if self.contrast_auto:
                self.last_low = float(low)
                self.last_high = float(high)
    def resolve_difference_contrast(self, auto_center: float, auto_max_abs: float) -> tuple[float, float]:
        candidate_center = float(auto_center)
        candidate = max(float(auto_max_abs), DIFFERENCE_MIN_HALF_RANGE)
        with self.settings_lock:
            if self.difference_manual_clim is not None:
                low, high = self.difference_manual_clim
                return (low + high) / 2.0, (high - low) / 2.0
            if self.contrast_auto:
                if not self.difference_contrast_valid:
                    self.last_difference_center = candidate_center
                    self.last_difference_max_abs = candidate
                else:
                    self.last_difference_center += DIFFERENCE_CENTER_SMOOTHING * (candidate_center - self.last_difference_center)
                    smoothing = DIFFERENCE_EXPAND_SMOOTHING if candidate > self.last_difference_max_abs else DIFFERENCE_CONTRACT_SMOOTHING
                    self.last_difference_max_abs += smoothing * (candidate - self.last_difference_max_abs)
                self.difference_contrast_valid = True
                return (self.last_difference_center, self.last_difference_max_abs)
            if not self.difference_contrast_valid:
                self.fixed_difference_max_abs = candidate
                self.fixed_difference_center = candidate_center
                self.last_difference_max_abs = candidate
                self.last_difference_center = candidate_center
                self.difference_contrast_valid = True
            return self.fixed_difference_center, self.fixed_difference_max_abs
    def set_difference_manual_clim(self, low: float, high: float) -> None:
        low = float(low)
        high = float(high)
        if not math.isfinite(low) or not math.isfinite(high):
            raise ValueError("CLim limits must be finite values")
        if high <= low:
            raise ValueError("CLim upper limit must be greater than the lower limit")
        with self.settings_lock:
            self.difference_manual_clim = (low, high)
    def clear_difference_manual_clim(self) -> None:
        with self.settings_lock:
            self.difference_manual_clim = None
            self.contrast_auto = True
            self.difference_contrast_valid = False
    def difference_contrast_state(self) -> tuple[str, tuple[float, float] | None]:
        with self.settings_lock:
            manual = self.difference_manual_clim
            if manual is not None:
                return "MANUAL", manual
            if self.contrast_auto:
                if not self.difference_contrast_valid:
                    return "AUTO", None
                center = self.last_difference_center
                half_range = self.last_difference_max_abs
                return "AUTO", (center - half_range, center + half_range)
            if not self.difference_contrast_valid:
                return "FIXED", None
            center = self.fixed_difference_center
            half_range = self.fixed_difference_max_abs
            return "FIXED", (center - half_range, center + half_range)
    def set_difference_display_average(self, temporal_count: int, spatial_binning: int, mean_filter_size: int) -> None:
        temporal_count = int(temporal_count)
        if temporal_count not in {1, 2, 4, 8}:
            raise ValueError("Difference temporal average count must be 1, 2, 4 or 8")
        spatial_binning = int(spatial_binning)
        if spatial_binning not in {1, 2, 4, 8}:
            raise ValueError("Display binning must be 1×1, 2×2, 4×4 or 8×8")
        mean_filter_size = int(mean_filter_size)
        if mean_filter_size not in {1, 2, 4}:
            raise ValueError("Mean filter must be off, 2×2 or 4×4")
        with self.settings_lock:
            changed = temporal_count != self.difference_temporal_average_count or spatial_binning != self.difference_spatial_binning or mean_filter_size != self.difference_mean_filter_size
            self.difference_temporal_average_count = temporal_count
            self.difference_spatial_binning = spatial_binning
            self.difference_mean_filter_size = mean_filter_size
            if changed:
                self.difference_average_reset_requested = True
                self.difference_contrast_valid = False
    def difference_display_average_state(self) -> tuple[int, int, int]:
        with self.settings_lock:
            return (self.difference_temporal_average_count, self.difference_spatial_binning, self.difference_mean_filter_size)
    def request_exposure_ms(self, exposure_ms: float) -> None:
        exposure_ms = float(exposure_ms)
        if not math.isfinite(exposure_ms):
            raise ValueError("Exposure time must be a finite value")
        if not 0.01 <= exposure_ms <= 10_000.0:
            raise ValueError("Exposure time must be within 0.01–10000 ms")
        with self.settings_lock:
            self.requested_exposure_s = exposure_ms / 1000.0
            self.exposure_update_requested = True
    def active_exposure_ms(self) -> float:
        with self.settings_lock:
            return self.active_exposure_s * 1000.0
    def _reset_difference_display_average(self) -> None:
        self._difference_average_sum = None
        self._difference_average_samples = 0
        self._difference_average_previous = None
        self._difference_average_start = math.nan
        self._difference_average_previous_start = math.nan
    def _difference_for_display(self, difference, temporal_count: int, spatial_binning: int, mean_filter_size: int, reset: bool, exposure_start: float=math.nan):
        if reset:
            self._reset_difference_display_average()
        source = np.asarray(difference, dtype=np.float32)
        if temporal_count <= 1:
            display = source
            self.display_window_start = exposure_start
        else:
            if self._difference_average_sum is not None and self._difference_average_sum.shape != source.shape:
                self._reset_difference_display_average()
            if self._difference_average_sum is None:
                self._difference_average_sum = source.copy()
                self._difference_average_samples = 1
                self._difference_average_start = exposure_start
            else:
                self._difference_average_sum += source
                self._difference_average_samples += 1
            samples = self._difference_average_samples
            block_start = self.__dict__.get("_difference_average_start", math.nan)
            if samples >= temporal_count:
                display = self._difference_average_sum / float(temporal_count)
                self._difference_average_previous = display
                self._difference_average_previous_start = block_start
                self.display_window_start = block_start
                self._difference_average_sum = None
                self._difference_average_samples = 0
            elif self._difference_average_previous is None:
                display = self._difference_average_sum / float(samples)
                self.display_window_start = block_start
            else:
                self.display_window_start = self.__dict__.get('_difference_average_previous_start', math.nan)
                remaining = temporal_count - samples
                display = self._difference_average_previous * (remaining / float(temporal_count)) + self._difference_average_sum / float(temporal_count)
        if spatial_binning > 1:
            display = spatial_bin_average_full_size(display, spatial_binning)
        if mean_filter_size > 1:
            display = mean_filter_full_size(display, mean_filter_size)
        return display
    def toggle_background(self) -> bool:
        with self.settings_lock:
            if self.background_mode == "off":
                self.background_mode = self.last_background_mode
                self.difference_contrast_valid = False
                self.difference_average_reset_requested = True
            else:
                self.last_background_mode = self.background_mode
                self.background_mode = "off"
            self.background_enabled = self.background_mode != "off"
            if self.background_enabled and self.background is None:
                self.background_capture_requested = True
            elif not self.background_enabled:
                self.background_capture_requested = False
            return self.background_enabled
    def set_background_mode(self, mode: str) -> str:
        if mode not in {"off", "plain", "tracking"}:
            raise ValueError(f"Unknown difference mode: {mode}")
        with self.settings_lock:
            previous_mode = self.background_mode
            self.background_mode = mode
            self.background_enabled = mode != "off"
            if mode != previous_mode and mode != "off":
                self.difference_contrast_valid = False
                self.difference_average_reset_requested = True
            if self.background_enabled:
                self.last_background_mode = mode
                if self.background is None:
                    self.background_capture_requested = True
            else:
                self.background_capture_requested = False
            return self.background_mode
    def capture_background(self) -> None:
        with self.settings_lock:
            if self.background_mode == "off":
                self.background_mode = self.last_background_mode
            self.background_enabled = True
            self.background_capture_requested = True
            self.difference_contrast_valid = False
            self.difference_average_reset_requested = True
    @staticmethod
    def _make_preview(image_raw, low: float, high: float):
        preview = np.asarray(image_raw).astype(np.float32)
        preview -= float(low)
        preview *= 255.0 / max(high - low, 1.0)
        np.clip(preview, 0.0, 255.0, out=preview)
        return preview.astype(np.uint8)
    def _put_latest(self, frame: CameraFrame) -> None:
        try:
            self.frames.put_nowait(frame)
            return
        except queue.Full:
            pass
        try:
            self.frames.get_nowait()
        except queue.Empty:
            pass
        try:
            self.frames.put_nowait(frame)
        except queue.Full:
            pass
    def _run(self) -> None:
        camera = None
        try:
            camera = pco.Camera()
            camera.default_configuration()
            camera.exposure_time = EXPOSURE_S
            camera.configuration = {"timestamp": "off", "metadata": "off"}
            camera.record(RING_BUFFER_FRAMES, "ring buffer")
            self.logger("PCO camera live preview started")
            while not self.stop_event.is_set():
                with self.settings_lock:
                    requested_exposure = self.requested_exposure_s if self.exposure_update_requested else None
                    self.exposure_update_requested = False
                    previous_exposure = self.active_exposure_s
                if requested_exposure is not None:
                    try:
                        camera.stop()
                        camera.exposure_time = requested_exposure
                        camera.record(RING_BUFFER_FRAMES, "ring buffer")
                    except BaseException as error:
                        self.logger(f"Camera exposure update failed: {error}")
                        try:
                            camera.stop()
                        except BaseException:
                            pass
                        camera.exposure_time = previous_exposure
                        camera.record(RING_BUFFER_FRAMES, "ring buffer")
                    else:
                        self.background = None
                        self._background_prepared = None
                        self._reset_difference_display_average()
                        with self.settings_lock:
                            self.active_exposure_s = requested_exposure
                            self.difference_contrast_valid = False
                            self.difference_average_reset_requested = True
                            if self.background_mode != "off":
                                self.background_capture_requested = True
                        self.logger(f'Camera exposure updated: {requested_exposure * 1000.0:g} ms; the difference background will be recaptured')
                if not self._wait_for_new_image(camera):
                    continue
                image_raw, _metadata = camera.image(0xFFFFFFFF)
                exposure_start = time.monotonic() - self.active_exposure_s - CAMERA_EXPOSURE_START_MARGIN_S
                image_raw = orient_camera_image(image_raw)
                with self.settings_lock:
                    auto = self.contrast_auto
                    fixed_low = self.fixed_low
                    fixed_high = self.fixed_high
                    last_low = self.last_low
                    last_high = self.last_high
                    background_mode = self.background_mode
                    background_enabled = background_mode != "off"
                    temporal_average_count = self.difference_temporal_average_count
                    spatial_binning = self.difference_spatial_binning
                    mean_filter_size = self.difference_mean_filter_size
                    reset_display_average = self.difference_average_reset_requested
                    if reset_display_average:
                        self.difference_average_reset_requested = False
                    capture_background = self.background_capture_requested
                    if capture_background:
                        self.background_capture_requested = False
                if capture_background:
                    self.background = image_raw.copy()
                    self.background_serial = next_background_serial()
                    self.logger("Camera background captured")
                if background_enabled:
                    if self.background is None:
                        self.background = image_raw.copy()
                        self.background_serial = next_background_serial()
                    prepared = self._background_prepared
                    if prepared is None or prepared.raw is not self.background:
                        prepared = DriftBackground(self.background)
                        self._background_prepared = prepared
                    if background_mode == "tracking":
                        difference, dx, dy, response = subtract_background_after_drift(image_raw, prepared)
                    else:
                        difference = image_raw.astype(np.float32)
                        difference -= prepared.float32
                        dx, dy, response = 0.0, 0.0, 0.0
                    display_difference = self._difference_for_display(difference, temporal_average_count, spatial_binning, mean_filter_size, reset_display_average, exposure_start)
                    window_start = self.display_window_start
                    preview = np.zeros(image_raw.shape, dtype=np.uint8)
                else:
                    difference = None
                    display_difference = None
                    window_start = math.nan
                    if reset_display_average:
                        self._reset_difference_display_average()
                    dx, dy, response = 0.0, 0.0, 0.0
                    if auto:
                        low, high = last_low, last_high
                    else:
                        low = fixed_low
                        high = fixed_high
                    preview = self._make_preview(image_raw, low, high)
                frame = CameraFrame(
                    raw=image_raw,
                    preview=preview,
                    difference=difference,
                    display_difference=display_difference,
                    exposure_ms=self.active_exposure_s * 1000.0,
                    raw_mean=_frame_mean(image_raw),
                    raw_max=int(np.max(image_raw)),
                    contrast_auto=auto,
                    background_enabled=background_enabled,
                    background_mode=background_mode,
                    drift_dx=dx,
                    drift_dy=dy,
                    drift_response=response,
                    temporal_average_count=temporal_average_count,
                    spatial_binning=spatial_binning,
                    mean_filter_size=mean_filter_size,
                    window_start_monotonic=window_start,
                    exposure_start_monotonic=exposure_start,
                    background_serial=self.background_serial if background_enabled else 0,
                    background_raw=self.background if background_enabled else None,
                )
                self._put_latest(frame)
        except BaseException as error:
            try:
                self.errors.put_nowait(error)
            except queue.Full:
                pass
        finally:
            if camera is not None:
                try:
                    camera.stop()
                except BaseException:
                    pass
                try:
                    camera.close()
                except BaseException:
                    pass
            self.logger("PCO camera live preview stopped")
class TkCameraWindow:
    def __init__(self, root: tk.Tk, app) -> None:
        if CAMERA_IMPORT_ERROR is not None:
            raise RuntimeError('Camera dependencies are missing. Install pco, numpy and Pillow, and check the PCO driver.\n\n' + str(CAMERA_IMPORT_ERROR))
        self.root = root
        self.app = app
        self.window = tk.Toplevel(root)
        self.window.withdraw()
        self.window.title(CAMERA_WINDOW)
        self.window.geometry(geometry_string(self.app.window_layout["camera"]))
        camera_geometry = self.app.window_layout["camera"]
        self.window.minsize(min(camera_geometry[0], max(360, int(520 * self.app.ui_scale))), min(camera_geometry[1], max(280, int(400 * self.app.ui_scale))))
        self.window.protocol("WM_DELETE_WINDOW", self.hide)
        self.window_visible = False
        self.canvas = tk.Canvas(self.window, bg="black", highlightthickness=0)
        self.canvas.pack(fill="both", expand=True)
        self.canvas.bind("<MouseWheel>", self._mouse_wheel)
        self.canvas.bind("<Button-4>", lambda event: self._zoom_at(event.x, event.y, 1))
        self.canvas.bind("<Button-5>", lambda event: self._zoom_at(event.x, event.y, -1))
        self.canvas.bind("<ButtonPress-1>", self._pan_start)
        self.canvas.bind("<B1-Motion>", self._pan_move)
        self.canvas.bind("<ButtonRelease-1>", self._pan_end)
        self.window.bind("<KeyPress-a>", self._toggle_contrast)
        self.window.bind("<KeyPress-A>", self._toggle_contrast)
        self.window.bind("<KeyPress-b>", self._toggle_background)
        self.window.bind("<KeyPress-B>", self._toggle_background)
        self.window.bind("<KeyPress-n>", self._capture_background)
        self.window.bind("<KeyPress-N>", self._capture_background)
        self.window.bind("<KeyPress-c>", self._clear_roi)
        self.window.bind("<KeyPress-C>", self._clear_roi)
        self.window.bind("<KeyPress-r>", self._reset_zoom)
        self.window.bind("<KeyPress-R>", self._reset_zoom)
        self.window.bind("<KeyPress-m>", lambda _event: self.app.toggle_100x_marker())
        self.window.bind("<KeyPress-M>", lambda _event: self.app.toggle_100x_marker())
        self.window.bind("<KeyPress-q>", lambda _event: self.app.request_close())
        self.window.bind("<Escape>", lambda _event: self.app.request_close())
        self.window.bind("<ButtonPress>", self._take_keyboard, add="+")
        self.window.focus_set()
        self.window.after_idle(lambda: force_english_input_mode(self.window))
        self.key_feedback = None
        self.worker = CameraAcquisitionWorker(self.app.thread_log)
        self.latest_frame: CameraFrame | None = None
        self.latest_display_image = None
        self.latest_display_geometry = None
        self.latest_display = None
        self.photo = None
        self.mapping = None
        self.zoom = 1.0
        self.center_x = None
        self.center_y = None
        self.panning = False
        self.pan_start_x = 0
        self.pan_start_y = 0
        self.pan_center_x = 0.0
        self.pan_center_y = 0.0
        self.selecting_roi = False
        self.roi_start = None
        self.roi_end = None
        self.roi = None
        self.roi_overlay_id = None
        self.roi_label_id = None
        self.objective_100x_marker_visible = False
        self.video_recorder: CameraVideoRecorder | None = None
        self.video_status_last_update = 0.0
        self.error_shown = False
        self.connection_announced = False
        self.after_id = None
        self.render_pause_count = 0
        self.render_pause_reason = ""
        self.worker.start()
        self.after_id = self.window.after(15, self._poll)
    @property
    def rendering_paused(self) -> bool:
        return self.render_pause_count > 0
    def show(self) -> None:
        try:
            if not self.window.winfo_exists():
                raise RuntimeError("Camera Live window has been closed")
            self.window.deiconify()
            self.window.lift()
            self.window.focus_set()
            self.window_visible = True
            self.app.camera_window_visibility_changed(True)
            if self.latest_frame is not None and not self.rendering_paused:
                self._draw(self.latest_frame)
        except tk.TclError as error:
            raise RuntimeError("Cannot show the Camera Live window") from error
    def hide(self) -> None:
        self.window_visible = False
        try:
            if self.window.winfo_exists():
                self.window.withdraw()
        except tk.TclError:
            pass
        self.app.camera_window_visibility_changed(False)
    def pause_rendering(self, reason: str = "background operation") -> None:
        self.render_pause_count += 1
        self.render_pause_reason = str(reason or "background operation")
        if self.render_pause_count != 1:
            return
        try:
            width = max(self.canvas.winfo_width(), 320)
            height = max(self.canvas.winfo_height(), 240)
            self.canvas.delete("camera_pause_overlay")
            self.canvas.create_rectangle(12, height - 48, width - 12, height - 12, fill='#1e293b', outline='#f4c542', width=2, tags='camera_pause_overlay')
            self.canvas.create_text(
                width / 2,
                height - 30,
                text=f"Live display paused · {self.render_pause_reason}",
                fill="#ffe66d",
                font=(self.app.ui_font_family, 11, "bold"),
                tags="camera_pause_overlay",
            )
            self.canvas.tag_raise("camera_pause_overlay")
        except tk.TclError:
            pass
    def resume_rendering(self) -> None:
        if self.render_pause_count <= 0:
            return
        self.render_pause_count -= 1
        if self.render_pause_count > 0:
            return
        self.render_pause_reason = ""
        try:
            self.canvas.delete("camera_pause_overlay")
        except tk.TclError:
            pass
        frame = self.latest_frame
        if frame is not None:
            try:
                if self.window.winfo_exists() and self.window_visible:
                    self._draw(frame)
            except tk.TclError:
                pass
    def stop(self) -> None:
        if self.video_recorder is not None:
            try:
                self.stop_video_recording()
            except BaseException as error:
                self.app.append_log(f"Camera recording finalisation failed: {error}")
        try:
            if self.after_id is not None and self.window.winfo_exists():
                self.window.after_cancel(self.after_id)
        except tk.TclError:
            pass
        self.after_id = None
        self.worker.stop()
    def close(self) -> None:
        self.window_visible = False
        self.stop()
        try:
            if self.window.winfo_exists():
                self.window.destroy()
        except tk.TclError:
            pass
    def _poll(self) -> None:
        try:
            error = self.worker.errors.get_nowait()
        except queue.Empty:
            error = None
        if error is not None and not self.error_shown:
            self.error_shown = True
            self.app.append_log(f"Camera error: {error}")
            self.app.camera_start_failed(error)
            messagebox.showerror('Camera acquisition failed', str(error) + '\n\nThe LED control window remains usable.', parent=self.root)
            return
        newest = None
        while True:
            try:
                newest = self.worker.frames.get_nowait()
            except queue.Empty:
                break
        if newest is not None:
            self.latest_frame = newest
            focus = self.app.__dict__.get("auto_focus")
            if focus is not None:
                focus.frame_arrived(newest)
            if not self.connection_announced:
                self.connection_announced = True
                self.app.camera_connection_ready()
            if (self.window_visible or self.video_recorder is not None) and (not self.selecting_roi) and (not self.rendering_paused):
                self._draw(newest)
            elif not self.selecting_roi:
                self._ingest_roi_values(newest)
                self.app.update_difference_status(newest.background_mode, newest.drift_dx, newest.drift_dy, newest.drift_response)
                self.app.camera_exposure_status_var.set(f'{newest.exposure_ms:g} ms')
        try:
            if self.window.winfo_exists():
                self.after_id = self.window.after(15, self._poll)
        except tk.TclError:
            self.after_id = None
    def _crop_bounds(self, width: int, height: int):
        if self.center_x is None:
            self.center_x = width / 2.0
        if self.center_y is None:
            self.center_y = height / 2.0
        crop_width = max(1, int(width / self.zoom))
        crop_height = max(1, int(height / self.zoom))
        self.center_x = float(np.clip(self.center_x, crop_width / 2.0, width - crop_width / 2.0))
        self.center_y = float(np.clip(self.center_y, crop_height / 2.0, height - crop_height / 2.0))
        x1 = int(np.clip(round(self.center_x - crop_width / 2.0), 0, width - crop_width))
        y1 = int(np.clip(round(self.center_y - crop_height / 2.0), 0, height - crop_height))
        return x1, y1, x1 + crop_width, y1 + crop_height
    def _draw(self, frame: CameraFrame) -> None:
        if self.rendering_paused:
            return
        image_height, image_width = frame.raw.shape[:2]
        canvas_width = max(self.canvas.winfo_width(), 320)
        canvas_height = max(self.canvas.winfo_height(), 240)
        x1, y1, x2, y2 = self._crop_bounds(image_width, image_height)
        visible_bounds = (x1, y1, x2, y2)
        active_difference_clim = None
        if frame.difference is not None:
            display_difference = frame.display_difference if frame.display_difference is not None else frame.difference
            auto_center, auto_max_abs = difference_contrast_parameters(display_difference, visible_bounds)
            active_center, active_max_abs = self.worker.resolve_difference_contrast(auto_center, auto_max_abs)
            preview = difference_preview(display_difference, max_abs=active_max_abs, center=active_center)
            active_difference_clim = (active_center - active_max_abs, active_center + active_max_abs)
        elif frame.contrast_auto:
            low, high = auto_contrast_limits(frame.raw, visible_bounds)
            self.worker.update_auto_contrast_bounds(low, high)
            preview = self.worker._make_preview(frame.raw, low, high)
        else:
            preview = frame.preview
        cropped = preview[y1:y2, x1:x2]
        scale = min(canvas_width / cropped.shape[1], canvas_height / cropped.shape[0])
        display_width = max(1, int(cropped.shape[1] * scale))
        display_height = max(1, int(cropped.shape[0] * scale))
        offset_x = (canvas_width - display_width) // 2
        offset_y = (canvas_height - display_height) // 2
        pil_image = Image.fromarray(cropped)
        pil_image = pil_image.resize((display_width, display_height), Image.Resampling.BILINEAR)
        display_array = np.asarray(pil_image, dtype=np.uint8)
        self.latest_display_image = display_array.copy()
        self.latest_display_geometry = (offset_x, offset_y, canvas_width, canvas_height)
        self.latest_display = (self.latest_display_image, self.latest_display_geometry, frame)
        self._record_current_8bit_view(display_array, offset_x, offset_y, canvas_width, canvas_height)
        self.photo = ImageTk.PhotoImage(pil_image)
        self.canvas.delete("all")
        self.roi_overlay_id = None
        self.roi_label_id = None
        self.canvas.create_image(offset_x, offset_y, image=self.photo, anchor="nw")
        self.mapping = {
            "crop_x1": x1,
            "crop_y1": y1,
            "crop_width": x2 - x1,
            "crop_height": y2 - y1,
            "offset_x": offset_x,
            "offset_y": offset_y,
            "display_width": display_width,
            "display_height": display_height,
            "image_width": image_width,
            "image_height": image_height,
        }
        margin = 35
        label_font = (self.app.ui_font_family, 46, "bold")
        self.canvas.create_text(margin, margin, text=CAMERA_CORNER_LABELS['nw'], fill='yellow', font=label_font, anchor='nw')
        self.canvas.create_text(margin, canvas_height - margin, text=CAMERA_CORNER_LABELS['sw'], fill='yellow', font=label_font, anchor='sw')
        self.canvas.create_text(canvas_width - margin, canvas_height - margin, text=CAMERA_CORNER_LABELS['se'], fill='yellow', font=label_font, anchor='se')
        self.canvas.create_text(canvas_width - margin, margin, text=CAMERA_CORNER_LABELS['ne'], fill='yellow', font=label_font, anchor='ne')
        if frame.difference is not None:
            contrast_mode, active_clim = self.worker.difference_contrast_state()
            if active_clim is None:
                contrast = contrast_mode
            else:
                contrast = f'{contrast_mode} CLim [{active_clim[0]:.4g}, {active_clim[1]:.4g}]'
        else:
            contrast = "AUTO" if frame.contrast_auto else "FIXED"
        temporal_average = frame.temporal_average_count
        spatial_binning = frame.spatial_binning
        mean_filter_size = frame.mean_filter_size
        average_text = f"Avg {temporal_average}"
        if spatial_binning > 1:
            average_text += f" + Bin {spatial_binning}x{spatial_binning}"
        if mean_filter_size > 1:
            average_text += f" + Mean {mean_filter_size}x{mean_filter_size}"
        exposure_text = f"Exp {frame.exposure_ms:g} ms"
        focus = self.app.__dict__.get("auto_focus")
        if frame.background_mode == "tracking" and focus is not None and focus.super_on:
            camera_status = (
                f"Super ON   dx {frame.drift_dx:+.2f}   dy {frame.drift_dy:+.2f}   "
                f"match {frame.drift_response:.2f}   {focus.super_overlay_text()}   {exposure_text}   "
                f"{average_text}   Contrast {contrast}"
            )
            status_color = "#ff9df0"
        elif frame.background_mode == "tracking":
            camera_status = f'Tracking subtraction ON   dx {frame.drift_dx:+.2f}   dy {frame.drift_dy:+.2f}   match {frame.drift_response:.2f}   {exposure_text}   {average_text}   Contrast {contrast}'
            status_color = "#6dff6d"
        elif frame.background_mode == "plain":
            camera_status = f'Plain subtraction ON   Zoom {self.zoom:.2f}x   {exposure_text}   {average_text}   Contrast {contrast}'
            status_color = "#ffe66d"
        else:
            camera_status = f'Zoom {self.zoom:.2f}x   {exposure_text}   Contrast {contrast}   BG OFF'
            status_color = "#6de7ff"
        self.canvas.create_text(canvas_width / 2, 17, text=camera_status, fill=status_color, font=(self.app.ui_font_family, self.app.ui_font_size + 2, 'bold'), anchor='n')
        self.canvas.create_text(
            canvas_width / 2,
            42,
            text=(
                f"Raw mean {frame.raw_mean:.1f}   max {frame.raw_max}   "
                "[A] contrast  [B] BG  [N] new BG  [C] clear ROI  "
                "[R] reset  [M] marker  [Q] quit"
            ),
            fill="yellow",
            font=(self.app.ui_font_family, self.app.ui_font_size),
            anchor="n",
        )
        if self.video_recorder is not None:
            self.canvas.create_text(12, 10, text='● REC', fill='#ff2d2d', font=(self.app.ui_font_family, self.app.ui_font_size + 2, 'bold'), anchor='nw')
        self._draw_roi(frame)
        self._draw_100x_marker()
        self._draw_measurement_marker()
        self._draw_key_feedback()
        self.app.update_difference_status(frame.background_mode, frame.drift_dx, frame.drift_dy, frame.drift_response)
        self.app.camera_exposure_status_var.set(f"{frame.exposure_ms:g} ms")
        if frame.difference is not None and active_difference_clim is not None:
            self.app.update_difference_histogram(display_difference, visible_bounds, active_difference_clim)
    def _canvas_to_image(self, x: int, y: int):
        if not self._on_image(x, y):
            return None
        mapping = self.mapping
        image_x = mapping['crop_x1'] + (x - mapping['offset_x']) / mapping['display_width'] * mapping['crop_width']
        image_y = mapping['crop_y1'] + (y - mapping['offset_y']) / mapping['display_height'] * mapping['crop_height']
        return image_x, image_y
    def start_video_recording(self, path: Path, fps: float) -> dict[str, object]:
        if self.video_recorder is not None:
            raise RuntimeError("Camera Live recording is already in progress")
        canvas_width = max(self.canvas.winfo_width(), 320)
        canvas_height = max(self.canvas.winfo_height(), 240)
        recorder = CameraVideoRecorder(path, fps, canvas_width, canvas_height)
        self.video_recorder = recorder
        self.video_status_last_update = 0.0
        return recorder.snapshot()
    def stop_video_recording(self) -> dict[str, object] | None:
        recorder = self.detach_video_recorder()
        if recorder is None:
            return None
        return recorder.stop()
    def detach_video_recorder(self) -> CameraVideoRecorder | None:
        recorder = self.video_recorder
        self.video_recorder = None
        return recorder
    def _record_current_8bit_view(self, display_image, offset_x: int, offset_y: int, canvas_width: int, canvas_height: int) -> None:
        recorder = self.video_recorder
        if recorder is None or not recorder.reserve_frame_slot():
            return
        frame = np.zeros((canvas_height, canvas_width), dtype=np.uint8)
        image = np.asarray(display_image, dtype=np.uint8)
        paste_height = min(image.shape[0], canvas_height - offset_y)
        paste_width = min(image.shape[1], canvas_width - offset_x)
        if paste_height > 0 and paste_width > 0:
            frame[offset_y:offset_y + paste_height, offset_x:offset_x + paste_width] = image[:paste_height, :paste_width]
        measurement_marker = self.app.current_camera_marker_text()
        if measurement_marker:
            font_scale = max(0.45, min(canvas_width, canvas_height) / 1400.0)
            thickness = max(1, int(round(font_scale * 2.0)))
            (text_width, text_height), baseline = cv2.getTextSize(measurement_marker, cv2.FONT_HERSHEY_SIMPLEX, font_scale, thickness)
            text_x = max(6, (canvas_width - text_width) // 2)
            text_y = canvas_height - 14
            cv2.rectangle(frame, (text_x - 5, text_y - text_height - 6), (min(canvas_width - 1, text_x + text_width + 5), text_y + baseline + 4), 0, -1)
            cv2.putText(frame, measurement_marker, (text_x, text_y), cv2.FONT_HERSHEY_SIMPLEX, font_scale, 255, thickness, cv2.LINE_AA)
        recorder.enqueue(frame)
        now = time.monotonic()
        if now - self.video_status_last_update >= 0.25:
            self.video_status_last_update = now
            self.app.update_camera_video_status(recorder.snapshot())
    def set_100x_marker_visible(self, visible: bool) -> None:
        self.objective_100x_marker_visible = bool(visible)
        if self.latest_frame is not None and not self.rendering_paused:
            self._draw(self.latest_frame)
    def _draw_100x_marker(self) -> None:
        self.canvas.delete("objective_100x_marker")
        mapping = self.mapping
        if not self.objective_100x_marker_visible or mapping is None:
            return
        image_x = mapping['image_width'] * OBJECTIVE_100X_MARKER_X_FRACTION
        image_y = mapping['image_height'] * OBJECTIVE_100X_MARKER_Y_FRACTION
        center_x = mapping['offset_x'] + (image_x - mapping['crop_x1']) / mapping['crop_width'] * mapping['display_width']
        center_y = mapping['offset_y'] + (image_y - mapping['crop_y1']) / mapping['crop_height'] * mapping['display_height']
        image_to_canvas_scale = min(mapping['display_width'] / mapping['crop_width'], mapping['display_height'] / mapping['crop_height'])
        radius = max(10.0, min(mapping['image_width'], mapping['image_height']) * OBJECTIVE_100X_MARKER_RADIUS_FRACTION * image_to_canvas_scale)
        self.canvas.create_oval(center_x - radius, center_y - radius, center_x + radius, center_y + radius, outline='#ff2d00', width=4, tags='objective_100x_marker')
        self.canvas.create_text(
            center_x,
            center_y - radius - 5,
            text="100× FOV",
            fill="#ff2d00",
            font=(self.app.ui_font_family, self.app.ui_font_size, "bold"),
            anchor="s",
            tags="objective_100x_marker",
        )
        self.canvas.tag_raise("objective_100x_marker")
    def _draw_measurement_marker(self) -> None:
        marker_text = self.app.current_camera_marker_text()
        if not marker_text:
            return
        canvas_width = max(self.canvas.winfo_width(), 320)
        canvas_height = max(self.canvas.winfo_height(), 240)
        text_id = self.canvas.create_text(canvas_width / 2, canvas_height - 12, text=marker_text, fill='#ffd54f', font=(self.app.ui_font_family, 11, 'bold'), anchor='s', tags='measurement_marker')
        bounds = self.canvas.bbox(text_id)
        if bounds is not None:
            left, top, right, bottom = bounds
            background_id = self.canvas.create_rectangle(left - 5, top - 3, right + 5, bottom + 3, fill='#111111', outline='#ffd54f', width=1, tags='measurement_marker')
            self.canvas.tag_lower(background_id, text_id)
        self.canvas.tag_raise("measurement_marker")
    def _ingest_roi_values(self, frame: CameraFrame) -> str:
        fresh = frame is not self.__dict__.get("_roi_ingested_frame")
        if fresh:
            self._roi_ingested_frame = frame
        roi = self.roi
        if self.selecting_roi and self.roi_start is not None and self.roi_end is not None:
            x1, x2 = sorted((self.roi_start[0], self.roi_end[0]))
            y1, y2 = sorted((self.roi_start[1], self.roi_end[1]))
            roi = {'cx': (x1 + x2) / 2.0, 'cy': (y1 + y2) / 2.0, 'w': x2 - x1, 'h': y2 - y1, 'angle': 0.0}
        if roi is None or self.mapping is None:
            return ""
        raw_roi_values = values_inside_rotated_roi(frame.raw, roi)
        raw_mean_value = None
        if raw_roi_values.size:
            raw_mean_value = float(np.mean(raw_roi_values))
            if not self.selecting_roi and fresh:
                self.app.ingest_led_roi_sample(raw_mean_value)
        if frame.difference is None:
            if raw_mean_value is None:
                label = "ROI outside image"
            else:
                label = f"Raw ROI mean {raw_mean_value:.3f} · BG not subtracted"
        else:
            processed_difference = frame.display_difference if frame.display_difference is not None else frame.difference
            roi_values = values_inside_rotated_roi(processed_difference, roi)
            if roi_values.size:
                mean_value = float(np.mean(roi_values))
                label = f"Processed ROI mean {mean_value:.3f}"
                if not self.selecting_roi and fresh:
                    self.app.ingest_moke_roi_sample(mean_value, getattr(frame, 'window_start_monotonic', math.nan))
                    self.app.ingest_2410_roi_sample(mean_value, getattr(frame, 'window_start_monotonic', math.nan))
            else:
                label = "ROI outside image"
        return label
    def _draw_roi(self, frame: CameraFrame) -> None:
        roi = self.roi
        if self.selecting_roi and self.roi_start is not None and self.roi_end is not None:
            x1, x2 = sorted((self.roi_start[0], self.roi_end[0]))
            y1, y2 = sorted((self.roi_start[1], self.roi_end[1]))
            roi = {'cx': (x1 + x2) / 2.0, 'cy': (y1 + y2) / 2.0, 'w': x2 - x1, 'h': y2 - y1, 'angle': 0.0}
        if roi is None or self.mapping is None:
            return
        label = self._ingest_roi_values(frame)
        self._update_roi_overlay(roi, label)
    def _update_roi_overlay(self, roi, label: str) -> None:
        mapping = self.mapping
        if roi is None or mapping is None:
            return
        def to_canvas(image_x, image_y):
            return (
                mapping["offset_x"]
                + (image_x - mapping["crop_x1"])
                / mapping["crop_width"]
                * mapping["display_width"],
                mapping["offset_y"]
                + (image_y - mapping["crop_y1"])
                / mapping["crop_height"]
                * mapping["display_height"],
            )
        canvas_points = [to_canvas(x, y) for x, y in rotated_roi_points(roi)]
        flattened = [coordinate for point in canvas_points for coordinate in point]
        if self.roi_overlay_id is None:
            self.roi_overlay_id = self.canvas.create_polygon(*flattened, outline='#6dff6d', fill='', width=2, tags=('roi_overlay',))
        else:
            self.canvas.coords(self.roi_overlay_id, *flattened)
        label_x, label_y = canvas_points[0]
        label_coordinates = (label_x, max(66, label_y - 5))
        if self.roi_label_id is None:
            self.roi_label_id = self.canvas.create_text(
                *label_coordinates,
                text=label,
                fill="#6dff6d",
                font=(self.app.ui_font_family, self.app.ui_font_size, "bold"),
                anchor="sw",
                tags=("roi_overlay",),
            )
        else:
            self.canvas.coords(self.roi_label_id, *label_coordinates)
            self.canvas.itemconfigure(self.roi_label_id, text=label)
        self.canvas.tag_raise("roi_overlay")
    def _update_selection_overlay(self) -> None:
        if not self.selecting_roi or self.roi_start is None or self.roi_end is None:
            return
        x1, x2 = sorted((self.roi_start[0], self.roi_end[0]))
        y1, y2 = sorted((self.roi_start[1], self.roi_end[1]))
        selection = {'cx': (x1 + x2) / 2.0, 'cy': (y1 + y2) / 2.0, 'w': x2 - x1, 'h': y2 - y1, 'angle': 0.0}
        self._update_roi_overlay(selection, f"Selecting ROI · W {selection['w']:.1f} px · H {selection['h']:.1f} px")
    def edit_roi(self, action: str, steps: dict[str, float]) -> None:
        if self.roi is None:
            return
        if action == "rotate_left":
            self.roi["angle"] = (self.roi["angle"] - steps["A"]) % 180.0
        elif action == "rotate_right":
            self.roi["angle"] = (self.roi["angle"] + steps["A"]) % 180.0
        elif action == "width_minus":
            self.roi["w"] = max(2.0, self.roi["w"] - steps["W"])
        elif action == "width_plus":
            self.roi["w"] += steps["W"]
        elif action == "height_minus":
            self.roi["h"] = max(2.0, self.roi["h"] - steps["H"])
        elif action == "height_plus":
            self.roi["h"] += steps["H"]
        elif action == "move_left":
            self.roi["cx"] -= steps["X"]
        elif action == "move_right":
            self.roi["cx"] += steps["X"]
        elif action == "move_up":
            self.roi["cy"] -= steps["Y"]
        elif action == "move_down":
            self.roi["cy"] += steps["Y"]
        if self.latest_frame is not None:
            height, width = self.latest_frame.preview.shape[:2]
            self.roi["cx"] = float(np.clip(self.roi["cx"], 0, width - 1))
            self.roi["cy"] = float(np.clip(self.roi["cy"], 0, height - 1))
            self._draw(self.latest_frame)
        self.app.set_2410_roi(self.roi)
    def _on_image(self, x: int, y: int) -> bool:
        if self.mapping is None:
            return False
        m = self.mapping
        return m['offset_x'] <= x < m['offset_x'] + m['display_width'] and m['offset_y'] <= y < m['offset_y'] + m['display_height']
    def _mouse_wheel(self, event) -> None:
        self._zoom_at(event.x, event.y, 1 if event.delta > 0 else -1)
    def _zoom_at(self, x: int, y: int, direction: int) -> None:
        if not self._on_image(x, y):
            return
        m = self.mapping
        mouse_image_x = m['crop_x1'] + (x - m['offset_x']) / m['display_width'] * m['crop_width']
        mouse_image_y = m['crop_y1'] + (y - m['offset_y']) / m['display_height'] * m['crop_height']
        old_zoom = self.zoom
        self.zoom = min(self.zoom * ZOOM_FACTOR, MAX_ZOOM) if direction > 0 else max(self.zoom / ZOOM_FACTOR, MIN_ZOOM)
        if self.zoom == old_zoom:
            return
        new_width = m["image_width"] / self.zoom
        new_height = m["image_height"] / self.zoom
        relative_x = (mouse_image_x - m["crop_x1"]) / max(m["crop_width"], 1.0)
        relative_y = (mouse_image_y - m["crop_y1"]) / max(m["crop_height"], 1.0)
        self.center_x = mouse_image_x - relative_x * new_width + new_width / 2.0
        self.center_y = mouse_image_y - relative_y * new_height + new_height / 2.0
        if self.latest_frame is not None:
            self._draw(self.latest_frame)
    def _pan_start(self, event) -> None:
        if not self._on_image(event.x, event.y):
            return
        if event.state & 0x0001:
            if self.app.keithley_scan_running or self.app.magnet_scan_running or self.app.k6221_scan_running:
                self.app.difference_status_var.set("The ROI cannot be reselected during a scan")
                return
            image_point = self._canvas_to_image(event.x, event.y)
            if image_point is None:
                return
            self.selecting_roi = True
            self.panning = False
            self.roi_start = image_point
            self.roi_end = image_point
            self._update_selection_overlay()
            return
        self.panning = True
        self.pan_start_x = event.x
        self.pan_start_y = event.y
        self.pan_center_x = self.center_x
        self.pan_center_y = self.center_y
    def _pan_move(self, event) -> None:
        if self.selecting_roi:
            image_point = self._canvas_to_image(event.x, event.y)
            if image_point is not None:
                self.roi_end = image_point
                self._update_selection_overlay()
            return
        if not self.panning or self.mapping is None:
            return
        m = self.mapping
        self.center_x = self.pan_center_x - (event.x - self.pan_start_x) * m['crop_width'] / m['display_width']
        self.center_y = self.pan_center_y - (event.y - self.pan_start_y) * m['crop_height'] / m['display_height']
        if self.latest_frame is not None:
            self._draw(self.latest_frame)
    def _pan_end(self, event) -> None:
        if self.selecting_roi:
            image_point = self._canvas_to_image(event.x, event.y)
            if image_point is not None:
                self.roi_end = image_point
            self.selecting_roi = False
            if self.roi_start is not None and self.roi_end is not None:
                x1, x2 = sorted((self.roi_start[0], self.roi_end[0]))
                y1, y2 = sorted((self.roi_start[1], self.roi_end[1]))
                if x2 - x1 >= 2 and y2 - y1 >= 2:
                    self.roi = {'cx': (x1 + x2) / 2.0, 'cy': (y1 + y2) / 2.0, 'w': x2 - x1, 'h': y2 - y1, 'angle': 0.0}
                    self.app.set_2410_roi(self.roi)
            if self.latest_frame is not None:
                self._draw(self.latest_frame)
            return
        self.panning = False
    def _clear_roi(self, _event=None) -> None:
        had_roi = self.roi is not None
        self.app.clear_camera_roi()
        if self.roi is not None:
            self.show_key_feedback("[C] ROI not cleared: a scan is running", "#ff8a80")
        else:
            self.show_key_feedback("[C] ROI cleared" if had_roi else "[C] no ROI to clear", "#7cff7c")
    def _take_keyboard(self, _event=None) -> None:
        try:
            focused = self.window.focus_get()
        except (tk.TclError, KeyError):
            focused = None
        try:
            if focused is None or focused.winfo_toplevel() is not self.window:
                self.window.focus_force()
        except tk.TclError:
            return
        force_english_input_mode(self.window)
    def show_key_feedback(self, text: str, colour: str, seconds: float = 2.5) -> None:
        self.key_feedback = (text, time.monotonic() + seconds, colour)
        self.app.append_log(f"Camera Live: {text}")
        if self.latest_frame is not None and not self.rendering_paused:
            self._draw(self.latest_frame)
        self._draw_key_feedback()
    def _draw_key_feedback(self) -> None:
        self.canvas.delete("key_feedback")
        feedback = self.__dict__.get("key_feedback")
        if not feedback or time.monotonic() > feedback[1]:
            self.key_feedback = None
            return
        text, _until, colour = feedback
        self.canvas.create_text(
            max(1, self.canvas.winfo_width()) / 2, 68, text=text, fill=colour,
            font=(self.app.ui_font_family, self.app.ui_font_size + 2, "bold"),
            anchor="n", tags=("key_feedback",),
        )
    def clear_roi_selection(self) -> None:
        self.selecting_roi = False
        self.panning = False
        self.roi_start = None
        self.roi_end = None
        self.roi = None
        self.canvas.delete("roi_overlay")
        self.roi_overlay_id = None
        self.roi_label_id = None
        if self.latest_frame is not None and not self.rendering_paused:
            self._draw(self.latest_frame)
    def _toggle_contrast(self, _event=None) -> None:
        automatic = self.worker.toggle_contrast()
        self.app.append_log("Camera contrast: " + ("auto" if automatic else "fixed"))
    def toggle_background(self) -> bool:
        previous = self.worker.background_mode
        enabled = self.worker.toggle_background()
        mode = self.worker.background_mode
        if mode != "off" and mode != previous:
            self.app.reset_difference_live_time_window()
        mode_label = {"off": "off", "plain": "plain difference", "tracking": "drift-tracking difference"}[mode]
        self.app.append_log("Difference mode: " + mode_label)
        return enabled
    def set_background_mode(self, mode: str) -> str:
        previous = self.worker.background_mode
        selected = self.worker.set_background_mode(mode)
        if selected != "off" and selected != previous:
            self.app.reset_difference_live_time_window()
        mode_label = {"off": "off", "plain": "plain difference", "tracking": "drift-tracking difference"}[selected]
        self.app.append_log("Difference mode: " + mode_label)
        return selected
    def capture_background(self) -> None:
        focus = self.app.__dict__.get("auto_focus")
        if focus is not None:
            focus.note_capture_request()
        self.worker.capture_background()
        self.app.reset_difference_live_time_window(restart_clock=True)
        self.app.append_log("Recapturing the background from the next frame…")
    def _toggle_background(self, _event=None) -> None:
        if self.app.keithley_scan_running or self.app.magnet_scan_running or self.app.k6221_scan_running:
            self.app.difference_status_var.set("The difference mode cannot be changed during a scan")
            return
        self.toggle_background()
    def _capture_background(self, _event=None) -> None:
        if self.app.keithley_scan_running or self.app.magnet_scan_running or self.app.k6221_scan_running:
            self.app.difference_status_var.set("The background cannot be recaptured during a scan")
            return
        self.capture_background()
    def _reset_zoom(self, _event=None) -> None:
        self.zoom = 1.0
        self.center_x = None
        self.center_y = None
        if self.latest_frame is not None:
            self._draw(self.latest_frame)
SCAN_FILE_NAME_PROMPT = "Optional file name (leave blank for a timestamped default):"
WINDOWS_RESERVED_FILE_NAMES = frozenset({'CON', 'PRN', 'AUX', 'NUL', *(f'COM{i}' for i in range(1, 10)), *(f'LPT{i}' for i in range(1, 10))})
def scan_file_stem(name: str) -> str:
    stem = str(name).strip()
    if not stem:
        return ""
    if stem.lower().endswith(".csv"):
        stem = stem[:-4]
    if not stem or stem.endswith(('.', ' ')) or re.search('[<>:"/\\\\|?*\\x00-\\x1f]', stem) or (stem.split('.')[0].upper() in WINDOWS_RESERVED_FILE_NAMES):
        raise ValueError("Use a valid Windows file name without a path.")
    return stem
def ask_scan_file_stem(parent, title: str) -> str | None:
    name = simpledialog.askstring(title, SCAN_FILE_NAME_PROMPT, parent=parent)
    if name is None:
        return None
    try:
        return scan_file_stem(name)
    except ValueError as error:
        messagebox.showerror(title, str(error), parent=parent)
        return None
def make_scan_run_folder(parent: Path, stem: str) -> Path:
    suffix = 0
    while True:
        directory = Path(parent) / (f"{stem}_{suffix:02d}" if suffix else stem)
        try:
            directory.mkdir()
        except FileExistsError:
            suffix += 1
            continue
        return directory
def scan_log_line(name: str, details: dict) -> str:
    record = {'timestamp': datetime_module.datetime.now().astimezone().isoformat(timespec='milliseconds'), 'event': name, **details}
    return json.dumps(record, ensure_ascii=False, default=str) + "\n"
SCAN_PLOT_SNAPSHOT_SETTLE_S = 0.05
class ScanRunRecorder:
    FIELDNAMES: tuple[str, ...] | None = None
    def __init__(self, parent: Path, page: str, name: str='', settings: dict | None=None, *, label: str | None=None) -> None:
        self.page, self.label = page, label or page
        stem = name or self._default_stem()
        if scan_file_stem(stem) != stem:
            raise ValueError(f"{stem!r} is not a valid file name for the run folder")
        self.directory = make_scan_run_folder(Path(parent), stem)
        stem = self.directory.name
        self.csv_path = self.directory / f"{stem}.csv"
        self.log_path = self.directory / f"{stem}.log"
        self.lock = threading.Lock()
        self.failure: BaseException | None = None
        self.closed = False
        self.other_folders: list[Path] = []
        _OPEN_SCAN_RUNS.add(self)
        self.rows_written = 0
        self.fieldnames = None if self.FIELDNAMES is None else list(self.FIELDNAMES)
        try:
            for path, encoding in ((self.csv_path, "utf-8-sig"), (self.log_path, "utf-8")):
                with path.open("x", encoding=encoding, newline=""):
                    pass
            if self.fieldnames is not None:
                with self.csv_path.open("a", newline="", encoding="utf-8-sig") as handle:
                    csv.DictWriter(handle, fieldnames=self.fieldnames).writeheader()
                    self._sync(handle)
            if settings is not None:
                self.event("run_prepared", **self._prepared_details(name, settings))
                failure = self.failure
                if failure is not None:
                    self.close("not_started", error=str(failure))
                    raise failure
        except BaseException:
            self.closed = True
            raise
    def also_saves_into(self, folder) -> None:
        self.other_folders.append(Path(folder))
    def _default_stem(self) -> str:
        return f"{self.page}_{time.strftime('%Y%m%d_%H%M%S')}"
    def _prepared_details(self, name: str, settings: dict) -> dict:
        return dict(program=Path(__file__).name, app_version=APP_VERSION, python_version=sys.version,
                    file_name=name, run_folder=str(self.directory), csv_path=str(self.csv_path),
                    log_path=str(self.log_path), settings=settings)
    @staticmethod
    def _sync(handle) -> None:
        handle.flush()
        os.fsync(handle.fileno())
    def _append(self, text: str) -> None:
        with self.log_path.open("a", encoding="utf-8") as handle:
            handle.write(text)
            self._sync(handle)
    def event(self, name: str, /, **details) -> bool:
        with self.lock:
            if self.closed:
                return False
            try:
                self._append(scan_log_line(name, details))
                return True
            except Exception as error:
                if self.failure is None:
                    self.failure = error
                return False
    def note(self, text: str) -> bool:
        return self.event("note", text=str(text))
    def check(self) -> None:
        error = self.failure
        if error is not None:
            raise RuntimeError(f"The {self.label} log could not be written ({error}); the scan stopped") from error
    def append_row(self, row: dict) -> None:
        with self.lock:
            if self.closed:
                raise RuntimeError(f"The {self.label} live CSV is closed")
            first = self.fieldnames is None
            fields = list(row) if first else self.fieldnames
            known = set(fields)
            extra = [str(key) for key in row if key not in known]
            if extra:
                raise ValueError(f"The {self.label} live CSV has no column for {', '.join(extra)}; the row was not written, so that the columns do not shift")
            with self.csv_path.open("a", newline="", encoding="utf-8-sig") as handle:
                writer = csv.DictWriter(handle, fieldnames=fields, restval="")
                if first:
                    writer.writeheader()
                writer.writerow(row)
                self._sync(handle)
            self.fieldnames = fields
            self.rows_written += 1
    def write_header(self, fieldnames) -> None:
        with self.lock:
            if self.closed:
                raise RuntimeError(f"The {self.label} live CSV is closed")
            if self.fieldnames is not None:
                return
            fields = [str(name) for name in fieldnames]
            with self.csv_path.open("a", newline="", encoding="utf-8-sig") as handle:
                csv.DictWriter(handle, fieldnames=fields).writeheader()
                self._sync(handle)
            self.fieldnames = fields
    def close(self, outcome: str, /, **details) -> list[str]:
        with self.lock:
            if self.closed:
                return []
            self.closed = True
            try:
                self._append(scan_log_line("run_finished", dict(outcome=outcome, **details)))
            except Exception as error:
                return [f"Failed to write the closing log entry: {error}"]
            return []
class STFMRScanRecorder(ScanRunRecorder):
    FIELDNAMES = (
        "index", "frequency_index", "loop", "point_in_loop", "elapsed_s",
        "meter", "current_a", "field_g", "x_v", "y_v", "voltage_v",
        "phase_deg", "reference_frequency_hz", "reference_valid",
        "microwave_frequency_ghz", "microwave_power_dbm",
        "modulation_frequency_hz", "mfli_timeconstant_s", "sr830_ref_in",
        "sr830_sensitivity_index", "sr830_sensitivity_full_scale_v",
        "sr830_auto_range_action", "timestamp_iso",
        "mfli_input_overload", "mfli_device_status_flags",
        "mfli_auto_range_enabled", "mfli_input_range_v",
        "mfli_input_utilization", "mfli_auto_range_action",
        "sr830_time_constant_s",
        "settle_s", "effective_settle_s", "acquire_s", "sample_count",
        "stage_angle_deg",
        "magnet_supply", "magnet_measured_current_a",
    )
    def __init__(self, parent: Path, settings: dict[str, object], name: str = "") -> None:
        super().__init__(parent, "STFMR", name, settings)
    def _default_stem(self) -> str:
        return "STFMR_field_scan_" + datetime_module.datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    def _prepared_details(self, name: str, settings: dict) -> dict:
        return dict(csv_path=str(self.csv_path), settings=settings)
    def append_point(self, row: dict[str, object]) -> None:
        self.append_row(row)
    def close(self, outcome: str, /, **details) -> list[str]:
        return super().close(outcome, saved_points=self.rows_written, **details)
class SHHVScanRecorder(ScanRunRecorder):
    def __init__(self, parent: Path, stem: str, page: str = "SHHV") -> None:
        super().__init__(parent, page, stem)
def begin_scan_run(parent, page_label: str, folder_title: str, initial_dir, settings: dict, *, prefix: str | None=None, make=None) -> ScanRunRecorder | None:
    where = {"initialdir": str(initial_dir)} if initial_dir else {}
    folder = filedialog.askdirectory(parent=parent, title=folder_title, **where)
    if not folder:
        return None
    typed = ask_scan_file_stem(parent, f"{page_label} file name")
    if typed is None:
        return None
    try:
        if make is not None:
            return make(Path(folder), typed)
        return ScanRunRecorder(Path(folder), prefix or page_label, typed, settings, label=page_label)
    except Exception as error:
        messagebox.showerror(f'{page_label} run folder', f'Could not create the run folder and its files; the scan was not started: {error}', parent=parent)
        return None
class ScanCloseHandoff:
    def __init__(self) -> None:
        self.lock = threading.Lock()
        self.active = False
        self.cleanup = None
    def begin(self) -> None:
        with self.lock:
            self.active = True
    def defer(self, cleanup) -> bool:
        with self.lock:
            if not self.active:
                return False
            self.cleanup = cleanup
            return True
    def end(self) -> None:
        with self.lock:
            self.active = False
            cleanup, self.cleanup = self.cleanup, None
        if cleanup is not None:
            cleanup()
ZERO_SENT_NOT_READ_BACK = "0 A sent, not read back"
SCAN_ZERO_OK_STATES = ("zeroed", "not connected", ZERO_SENT_NOT_READ_BACK)
def zero_scan_outputs(steps) -> dict[str, str]:
    results = {}
    for label, zero in steps:
        try:
            state = zero()
            results[label] = state if state in ("not connected", ZERO_SENT_NOT_READ_BACK) else "zeroed"
        except Exception as error:
            results[label] = f"zero FAILED: {error}"
    return results
def scan_end_outputs_text(results, outputs=(), check: bool = True, together: str = "") -> str:
    def joined(names):
        return names[0] if len(names) == 1 else ", ".join(names[:-1]) + " and " + names[-1]
    results = dict(results or {})
    names = list(outputs) + [name for name in results if name not in outputs]
    together = together or (joined(names) if names else "the outputs")
    if not results:
        return f'{together} not confirmed zeroed' + ((': check it' if len(names) == 1 else ': check them') if check else '')
    states = [results.get(name, "") for name in names]
    if all(state == "zeroed" for state in states):
        return f"{together} zeroed"
    failed = [name for name, state in zip(names, states) if state not in SCAN_ZERO_OK_STATES]
    if len(names) > 1 and len(failed) == len(names):
        text = "zero FAILED: " + joined(failed)
    else:
        text = '; '.join((f'{name} {state}' if state in SCAN_ZERO_OK_STATES else f'{name} zero FAILED' for name, state in zip(names, states)))
    if check and failed:
        text += ": check it" if len(failed) == 1 else ": check them"
    return text
PAIR_FLIP_LIMIT = 8
FOCUS_RANGE_UM = 10.0
FOCUS_STEP_UM = 0.5
FOCUS_BACKLASH_STEPS = 2
FOCUS_LOCAL_HALF_STEPS = 3
FOCUS_PAST_PEAK_STEPS = 2
FOCUS_MIN_CONTRAST = 0.03
FOCUS_MIN_GAIN = 0.02
FOCUS_FRAMES_PER_POSITION = 2
FOCUS_SETTLE_S = 0.5
FOCUS_FRAME_TIMEOUT_S = 10.0
FOCUS_MOVE_TIMEOUT_S = 10.0
FOCUS_IDLE_INTERVAL_S = 30.0
FOCUS_IDLE_TICK_MS = 1000
FOCUS_STOP_WAIT_S = 15.0
FOCUS_DOWNSAMPLE_TARGET_PX = 512
FOCUS_POSITION_TOLERANCE_UM = 0.02
FOCUS_CSV_COLUMN = "focus_position_um"
FOCUS_DIALOG_TITLE = "Auto focus"
def focus_sharpness(image, roi=None) -> float:
    if np is None:
        raise RuntimeError("numpy is required for the auto focus")
    array = np.asarray(image, dtype=np.float64)
    if array.ndim == 3:
        array = array.mean(axis=2)
    if array.ndim != 2 or min(array.shape) < 3:
        raise ValueError(f"Auto focus needs a 2-D image, not shape {array.shape}")
    if roi is not None:
        min_y, max_y, min_x, max_x, mask = _rotated_roi_mask(roi, array.shape[0], array.shape[1])
        if mask is None or mask.shape[0] < 3 or mask.shape[1] < 3:
            raise ValueError("the ROI lies outside the image or is under 3 x 3 pixels")
        crop = array[min_y:max_y, min_x:max_x]
        inner = mask[1:-1, 1:-1]
        if not inner.any():
            raise ValueError("the ROI is too thin for the auto focus (under 3 pixels across)")
        mean = float(np.mean(crop[mask]))
        if not math.isfinite(mean) or mean <= 0.0:
            return 0.0
        laplacian = crop[:-2, 1:-1] + crop[2:, 1:-1] + crop[1:-1, :-2] + crop[1:-1, 2:] - 4.0 * crop[1:-1, 1:-1]
        value = float(np.var(laplacian[inner])) / (mean * mean)
        return value if math.isfinite(value) else 0.0
    factor = max(1, int(math.ceil(max(array.shape) / FOCUS_DOWNSAMPLE_TARGET_PX)))
    if factor > 1 and min(array.shape) // factor >= 3:
        height = array.shape[0] // factor * factor
        width = array.shape[1] // factor * factor
        array = array[:height, :width].reshape(height // factor, factor, width // factor, factor).mean(axis=(1, 3))
    mean = float(np.mean(array))
    if not math.isfinite(mean) or mean <= 0.0:
        return 0.0
    laplacian = array[:-2, 1:-1] + array[2:, 1:-1] + array[1:-1, :-2] + array[1:-1, 2:] - 4.0 * array[1:-1, 1:-1]
    value = float(np.var(laplacian)) / (mean * mean)
    return value if math.isfinite(value) else 0.0
class FocusError(RuntimeError):
    pass
class FocusCancelled(RuntimeError):
    pass
@dataclass
class FocusResult:
    kind: str
    reference_um: float
    start_um: float
    best_um: float
    start_score: float
    best_score: float
    peak_found: bool
    at_window_edge: bool
    moves: int
    positions: list
class FocusSearch:
    def __init__(self, reference_um, current_um, max_position_um, move, measure, cancelled,
                 *, range_um=FOCUS_RANGE_UM, step_um=FOCUS_STEP_UM, log=None,
                 min_contrast=None, min_gain=None, name="Auto focus", describe=None):
        self.reference_um = float(reference_um)
        self.min_contrast = FOCUS_MIN_CONTRAST if min_contrast is None else float(min_contrast)
        self.min_gain = FOCUS_MIN_GAIN if min_gain is None else float(min_gain)
        self.name = str(name)
        self.describe = describe or (lambda score: f"scores {score:.6g}")
        self.range_um = float(range_um)
        self.step_um = float(step_um)
        self.max_position_um = float(max_position_um)
        self.move, self.measure, self.cancelled = move, measure, cancelled
        self.log = log or (lambda text: None)
        steps = int(math.floor(self.range_um / self.step_um + 1e-9))
        self.k_min = max(-steps, int(math.ceil(-self.reference_um / self.step_um - 1e-9)))
        self.k_max = min(steps, int(math.floor((self.max_position_um - self.reference_um) / self.step_um + 1e-09)))
        offset = (float(current_um) - self.reference_um) / self.step_um
        k = int(round(offset))
        if abs(float(current_um) - self.position(k)) > FOCUS_POSITION_TOLERANCE_UM:
            raise FocusError(f'the motor at {float(current_um):g} µm is not on the {self.step_um:g} µm grid of the focus reference {self.reference_um:g} µm')
        if not self.k_min <= k <= self.k_max:
            raise FocusError(f'the motor at {float(current_um):g} µm is outside the focus window {self.position(self.k_min):g}–{self.position(self.k_max):g} µm')
        self.k = self.start_k = k
        self.moves = 0
        self.positions: list[tuple[float, float]] = []
    def position(self, k: int) -> float:
        return round(self.reference_um + k * self.step_um, 6)
    def _check_cancel(self) -> None:
        if self.cancelled():
            raise FocusCancelled("auto focus stopped")
    def _move_to(self, k: int) -> None:
        self._check_cancel()
        target = self.position(k)
        if not self.k_min <= k <= self.k_max or abs(target - self.reference_um) > self.range_um + 1e-09 or (not 0.0 <= target <= self.max_position_um):
            raise FocusError(f"focus target {target:g} µm is outside the focus window")
        self.move(target)
        self.k = k
        self.moves += 1
    def goto(self, k: int) -> None:
        if k == self.k:
            return
        if k < self.k:
            below = max(self.k_min, k - FOCUS_BACKLASH_STEPS)
            if below < k:
                self._move_to(below)
        self._move_to(k)
    def _score_here(self) -> float:
        self._check_cancel()
        score = float(self.measure())
        self.positions.append((self.position(self.k), score))
        self.log(f"{self.name}: {self.position(self.k):g} µm {self.describe(score)}")
        return score
    def _score_at(self, k: int, scores: dict) -> float:
        self.goto(k)
        scores[k] = self._score_here()
        return scores[k]
    @staticmethod
    def _contrast(scores: dict) -> float:
        best = max(scores.values())
        return (best - min(scores.values())) / best if best > 0 else 0.0
    def search(self) -> FocusResult:
        start_k = self.k
        scores: dict[int, float] = {}
        start_score = self._score_here()
        scores[start_k] = start_score
        low = max(self.k_min, start_k - FOCUS_LOCAL_HALF_STEPS)
        high = min(self.k_max, start_k + FOCUS_LOCAL_HALF_STEPS)
        for k in range(low, high + 1):
            self._score_at(k, scores)
        while True:
            best = max(scores, key=scores.get)
            top, bottom = max(scores), min(scores)
            if top - best < FOCUS_PAST_PEAK_STEPS and top < self.k_max:
                self._score_at(top + 1, scores)
                continue
            if best - bottom < FOCUS_PAST_PEAK_STEPS and bottom > self.k_min:
                block = max(self.k_min, bottom - 2 * FOCUS_PAST_PEAK_STEPS)
                for k in range(block, bottom):
                    self._score_at(k, scores)
                continue
            break
        if self._contrast(scores) < self.min_contrast:
            self.log(f"{self.name}: no clear peak near the start; sweeping the whole window")
            scores = {}
            for k in range(self.k_min, self.k_max + 1):
                self._score_at(k, scores)
        peak = self._contrast(scores) >= self.min_contrast
        best = max(scores, key=scores.get) if peak else start_k
        self.goto(best)
        final_score = self._score_here()
        return FocusResult(
            "search", self.reference_um, self.position(start_k), self.position(best),
            start_score, final_score, peak, peak and best in (self.k_min, self.k_max),
            self.moves, list(self.positions),
        )
    def check(self) -> FocusResult:
        start_k = self.k
        start_score = self._score_here()
        scores = {start_k: start_score}
        for k in (start_k + 1, start_k - 1):
            if self.k_min <= k <= self.k_max:
                self._score_at(k, scores)
        gain = 1.0 + self.min_gain
        best_k = max(scores, key=scores.get)
        at_edge = False
        if best_k != start_k and scores[best_k] > start_score * gain:
            direction = best_k - start_k
            k = best_k + direction
            while True:
                if not self.k_min <= k <= self.k_max:
                    at_edge = True
                    break
                if self._score_at(k, scores) > scores[best_k] * gain:
                    best_k = k
                    k += direction
                    continue
                break
        else:
            best_k = start_k
        self.goto(best_k)
        return FocusResult('check', self.reference_um, self.position(start_k), self.position(best_k), start_score, scores[best_k], best_k != start_k, at_edge, self.moves, list(self.positions))
SUPER_GRID_TARGET_PX = 1024
SUPER_EDGE_PERCENTILE = 92.0
SUPER_EDGE_DILATE_PX = 2
SUPER_HIGHPASS_PX = 31
SUPER_BORDER_PX = 16
SUPER_MIN_EDGE_PIXELS = 16
SUPER_EPSILON = 1e-9
SUPER_MIN_CONTRAST = 0.10
SUPER_MIN_GAIN = 0.05
SUPER_LIVE_INTERVAL_S = 1.0
SUPER_AUTO_MIN_RESIDUAL = 0.06
SUPER_AUTO_RATIO = 1.5
SUPER_AUTO_COOLDOWN_S = 10.0
SUPER_MODE_LABEL = "Super"
def _super_block_mean(array, factor: int):
    if factor <= 1:
        return array
    height = array.shape[0] // factor * factor
    width = array.shape[1] // factor * factor
    return array[:height, :width].reshape(height // factor, factor, width // factor, factor).mean(axis=(1, 3))
def _super_sobel(array):
    p = np.pad(array, 1, mode="edge")
    gx = (p[:-2, 2:] + 2.0 * p[1:-1, 2:] + p[2:, 2:]) - (p[:-2, :-2] + 2.0 * p[1:-1, :-2] + p[2:, :-2])
    gy = (p[2:, :-2] + 2.0 * p[2:, 1:-1] + p[2:, 2:]) - (p[:-2, :-2] + 2.0 * p[:-2, 1:-1] + p[:-2, 2:])
    return gx / 8.0, gy / 8.0
def _super_dilate(mask, radius: int):
    out = mask.copy()
    for axis in (0, 1):
        for _ in range(int(radius)):
            grown = out.copy()
            if axis == 0:
                grown[1:] |= out[:-1]
                grown[:-1] |= out[1:]
            else:
                grown[:, 1:] |= out[:, :-1]
                grown[:, :-1] |= out[:, 1:]
            out = grown
    return out
def _super_box_mean(array, size: int):
    half = int(size) // 2
    size = 2 * half + 1
    if half < 1 or min(array.shape) <= half:
        return np.full(array.shape, float(np.mean(array)))
    padded = np.pad(array, half, mode="reflect")
    integral = np.pad(padded, ((1, 0), (1, 0))).cumsum(axis=0).cumsum(axis=1)
    height, width = array.shape
    total = integral[size:size + height, size:size + width] - integral[:height, size:size + width] - integral[size:size + height, :width] + integral[:height, :width]
    return total / float(size * size)
class EdgeResidualReference:
    def __init__(self, background, spatial_binning: int = 1, mean_filter_size: int = 1) -> None:
        if np is None:
            raise RuntimeError("numpy is required for Super")
        array = np.asarray(background, dtype=np.float64)
        if array.ndim != 2:
            raise ValueError(f"Super needs a 2-D BG, not shape {array.shape}")
        self.shape = array.shape
        self.spatial_binning = int(spatial_binning)
        self.mean_filter_size = int(mean_filter_size)
        processed = array.astype(np.float32)
        if self.spatial_binning > 1:
            processed = spatial_bin_average_full_size(processed, self.spatial_binning)
        if self.mean_filter_size > 1:
            processed = mean_filter_full_size(processed, self.mean_filter_size)
        binning = max(1, self.spatial_binning)
        needed = max(1, int(math.ceil(max(self.shape) / SUPER_GRID_TARGET_PX)))
        self.factor = binning * int(math.ceil(needed / binning))
        grid = _super_block_mean(np.asarray(processed, dtype=np.float64), self.factor)
        if min(grid.shape) <= 2 * SUPER_BORDER_PX + 4:
            raise ValueError(f"the image ({array.shape[1]} x {array.shape[0]}) is too small for Super")
        self.grid = grid
        self.gx, self.gy = _super_sobel(grid)
        valid = np.zeros(grid.shape, dtype=bool)
        border = SUPER_BORDER_PX
        valid[border:-border, border:-border] = True
        gradient = np.hypot(self.gx, self.gy)
        threshold = float(np.percentile(gradient[valid], SUPER_EDGE_PERCENTILE))
        core = (gradient > threshold) & valid
        if not math.isfinite(threshold) or threshold <= 0.0 or int(core.sum()) < SUPER_MIN_EDGE_PIXELS:
            raise ValueError("the BG shows no edges for Super to judge (a flat or dark image)")
        self.edge = _super_dilate(core, SUPER_EDGE_DILATE_PX)
        self.edge &= valid
        self.background_highpass = grid - _super_box_mean(grid, SUPER_HIGHPASS_PX)
    def window(self, drift_px: float = 0.0):
        extra = int(math.ceil(abs(float(drift_px)) / self.factor)) if math.isfinite(drift_px) else 0
        margin = SUPER_BORDER_PX + extra
        height, width = self.grid.shape
        if 2 * margin + 4 >= min(height, width):
            raise ValueError("the drift leaves too little of the image for Super")
        return (slice(margin, height - margin), slice(margin, width - margin))
def _super_roi_grid(reference: EdgeResidualReference, roi):
    key = tuple(float(roi[name]) for name in ("cx", "cy", "w", "h", "angle"))
    cache = reference.__dict__.setdefault("_roi_cache", {})
    cached = cache.get(key)
    if cached is not None:
        return cached
    height, width = reference.shape
    min_y, max_y, min_x, max_x, mask = _rotated_roi_mask(roi, height, width)
    full = np.zeros(reference.shape, dtype=np.float64)
    if mask is not None:
        full[min_y:max_y, min_x:max_x] = mask
    inside = _super_block_mean(full, reference.factor) >= 0.5
    if len(cache) >= 4:
        cache.clear()
    cache[key] = inside
    return inside
def edge_residual(difference, reference: EdgeResidualReference, drift_px: float = 0.0, roi=None) -> float:
    d = np.asarray(difference, dtype=np.float64)
    if d.shape != reference.shape:
        raise ValueError(f"the difference ({d.shape}) and the BG ({reference.shape}) differ in size")
    d = _super_block_mean(d, reference.factor)
    rows, cols = reference.window(drift_px)
    if roi is not None:
        inside = _super_roi_grid(reference, roi)[rows, cols]
        if int(inside.sum()) < 16:
            raise ValueError("the ROI is too small or outside the image for Super")
    else:
        inside = np.ones(d[rows, cols].shape, dtype=bool)
    regressors = [np.ones(int(inside.sum())), reference.grid[rows, cols][inside], reference.gx[rows, cols][inside], reference.gy[rows, cols][inside]]
    target = d[rows, cols][inside]
    gram = np.array([[float(np.vdot(a, b)) for b in regressors] for a in regressors])
    rhs = np.array([float(np.vdot(a, target)) for a in regressors])
    coefficients = np.linalg.lstsq(gram, rhs, rcond=None)[0]
    cleaned = d - (coefficients[0] + coefficients[1] * reference.grid + coefficients[2] * reference.gx + coefficients[3] * reference.gy)
    highpass = cleaned - _super_box_mean(cleaned, SUPER_HIGHPASS_PX)
    edge = reference.edge[rows, cols] & inside
    if int(edge.sum()) < SUPER_MIN_EDGE_PIXELS:
        raise ValueError('too few BG edges inside the ROI for Super' if roi is not None else 'too few BG edges left inside the image for Super')
    residual = float(np.mean(highpass[rows, cols][edge] ** 2))
    contrast = float(np.mean(reference.background_highpass[rows, cols][edge] ** 2))
    value = math.sqrt(residual / (contrast + SUPER_EPSILON))
    if not math.isfinite(value):
        raise ValueError("the edge residual is not finite")
    return value
class SuperFocusSearch(FocusSearch):
    def __init__(self, reference_um, current_um, max_position_um, move, measure_residual, cancelled, *, log=None, **options):
        def measure() -> float:
            value = float(measure_residual())
            if not math.isfinite(value) or value < 0.0:
                raise FocusError(f"the edge residual {value!r} is not usable")
            return 1.0 / max(value, SUPER_EPSILON)
        super().__init__(
            reference_um, current_um, max_position_um, move, measure, cancelled, log=log,
            min_contrast=SUPER_MIN_CONTRAST, min_gain=SUPER_MIN_GAIN, name="Super focus",
            describe=lambda score: f"edge residual {super_residual_text(SuperFocusSearch.residual(score))}",
            **options,
        )
    @staticmethod
    def residual(score: float) -> float:
        return 1.0 / score if score > 0 else math.inf
def super_residual_text(value) -> str:
    try:
        value = float(value)
    except (TypeError, ValueError):
        return "--"
    if not math.isfinite(value):
        return "--"
    return f"{value * 100.0:.2g} %" if value < 0.1 else f"{value * 100.0:.0f} %"
class AutoFocusManager:
    def __init__(self, app, keep_var=None, status_var=None) -> None:
        self.app = app
        self.keep_var = keep_var if keep_var is not None else tk.BooleanVar(value=False)
        self.status_var = status_var if status_var is not None else tk.StringVar(value='Focus: not run (needs the motor homed, the camera live and an ROI)')
        self.roi = None
        self.super_roi = None
        self.buttons: list = []
        self.ticks: list = []
        self.camera_ready = False
        self.lock = threading.Lock()
        self.cancel_event = threading.Event()
        self.running_kind: str | None = None
        self.keep_on = False
        self.reference_um: float | None = None
        self.expected_counts: int | None = None
        self.unknown_counts: int | None = None
        self.frames_after = -math.inf
        self.last_check_monotonic = -math.inf
        self.idle_after_id = None
        self.running_metric = "sharpness"
        self.super_on = False
        self.seen_serial = 0
        self.background_focus = None
        self.capture_request_counts = None
        self.super_serial = None
        self.super_reference_um: float | None = None
        self.super_reference_reason: str | None = "no BG has been captured yet"
        self.super_live_residual: float | None = None
        self.super_live_error: str | None = None
        self.super_start_residual: float | None = None
        self.super_best_residual: float | None = None
        self._live_busy = False
        self._live_last = -math.inf
        self._edge_lock = threading.Lock()
        self._edge_cache = None
    def _motor(self):
        return self.app.__dict__.get("motor_app")
    def _cancelled(self, stop_events=()) -> bool:
        return self.cancel_event.is_set() or bool(self.app.__dict__.get('closing')) or any((event.is_set() for event in stop_events))
    def _scan_running(self) -> bool:
        return bool(self.app.__dict__.get('magnet_scan_running') or self.app.__dict__.get('keithley_scan_running') or self.app.__dict__.get('k6221_scan_running'))
    def acquisition_busy(self) -> str | None:
        app = self.app
        if app.__dict__.get("magnet_scan_collecting"):
            return "a MOKE magnet point is acquiring"
        if app.__dict__.get("keithley_collecting"):
            return "a MOKE-24 point is acquiring"
        camera = app.__dict__.get("camera_window")
        if camera is not None:
            if getattr(camera, "video_recorder", None) is not None or app.__dict__.get("camera_video_stopping"):
                return "Camera Live is recording"
            worker = getattr(camera, "worker", None)
            if worker is not None and getattr(worker, "background_capture_requested", False):
                return "a background is being captured"
        if app.__dict__.get("active_file_exports"):
            return "images are being saved"
        return None
    def position_for_row(self):
        motor = self._motor()
        if motor is None:
            return ""
        try:
            if not (motor.controller.connected and motor.homed):
                return ""
            counts = int(motor.command_counts)
            scale = float(motor.abs_counts_per_um)
        except (AttributeError, TypeError, ValueError):
            return ""
        if self.unknown_counts is not None and counts == self.unknown_counts:
            return ""
        return round(counts / scale, 4)
    def _log(self, text: str, recorder_attrs=()) -> None:
        self.app.thread_log(text)
        for attribute in recorder_attrs:
            self.app._scan_log(attribute, "note", text=str(text))
    def _call_on_tk(self, function, stop_events=(), timeout_s=FOCUS_MOVE_TIMEOUT_S):
        handoff = Future()
        def run():
            if not handoff.set_running_or_notify_cancel():
                return
            try:
                handoff.set_result(function())
            except BaseException as error:
                handoff.set_exception(error)
        self.app.post_ui(run)
        deadline = time.monotonic() + timeout_s
        while not handoff.done():
            if self._cancelled(stop_events) or time.monotonic() >= deadline:
                if handoff.cancel():
                    if self._cancelled(stop_events):
                        raise FocusCancelled("auto focus stopped")
                    raise FocusError(f'the program did not send the focus move within {timeout_s:g} s')
                break
            time.sleep(0.01)
        return handoff.result(timeout=timeout_s)
    def _move(self, target_um: float, stop_events=(), recorder_attrs=(), reference_um=None) -> None:
        motor = self._motor()
        if motor is None:
            raise FocusError("the focus motor is not attached")
        reference = self.reference_um if reference_um is None else float(reference_um)
        name = "Super focus" if self.running_metric == "super" else "Auto focus"
        whose = "the BG's focus" if self.running_metric == "super" else "the reference"
        def send():
            if self._cancelled(stop_events):
                raise FocusCancelled("auto focus stopped")
            if self.expected_counts is not None and motor.command_counts != self.expected_counts:
                raise FocusError("the focus motor was moved by another command during the auto focus")
            return motor.submit_focus_target(target_um, f'{target_um - reference:+.1f} µm from the reference {reference:g} µm')
        try:
            future, counts, travel_s = self._call_on_tk(send, stop_events)
        except (FocusCancelled, FocusError):
            raise
        except BaseException as error:
            raise FocusError(f"the focus move to {target_um:g} µm was refused: {error}") from error
        self._log(f'{name} move: absolute {target_um:g} µm ({target_um - reference:+.1f} µm from {whose} {reference:g} µm)', recorder_attrs)
        deadline = time.monotonic() + FOCUS_MOVE_TIMEOUT_S
        while not future.done():
            if self._cancelled(stop_events):
                raise FocusCancelled("auto focus stopped")
            if time.monotonic() >= deadline:
                self.unknown_counts = int(motor.command_counts)
                raise FocusError(f'the focus move to {target_um:g} µm was not confirmed within {FOCUS_MOVE_TIMEOUT_S:g} s')
            time.sleep(0.01)
        error = future.exception()
        if error is not None:
            self.unknown_counts = int(motor.command_counts)
            raise FocusError(f"the focus move to {target_um:g} µm failed: {error}")
        while motor.command_busy or motor.pending_target is not None or motor.command_counts != counts:
            if self._cancelled(stop_events):
                raise FocusCancelled("auto focus stopped")
            if time.monotonic() >= deadline:
                self.unknown_counts = int(motor.command_counts)
                raise FocusError(f"the focus move to {target_um:g} µm was not confirmed by the motor page")
            time.sleep(0.01)
        self.expected_counts = counts
        self.unknown_counts = None
        self.frames_after = time.monotonic() + float(travel_s) + FOCUS_SETTLE_S
    def _measure(self, stop_events=()) -> float:
        after = max(self.frames_after, time.monotonic())
        frames = []
        camera = self.app.__dict__.get("camera_window")
        latest = getattr(camera, "latest_frame", None)
        try:
            exposure_s = float(latest.exposure_ms) / 1000.0
        except (AttributeError, TypeError, ValueError):
            exposure_s = 0.0
        if not math.isfinite(exposure_s):
            exposure_s = 0.0
        deadline = time.monotonic() + FOCUS_FRAME_TIMEOUT_S + (FOCUS_FRAMES_PER_POSITION + 1) * exposure_s
        while len(frames) < FOCUS_FRAMES_PER_POSITION:
            if self._cancelled(stop_events):
                raise FocusCancelled("auto focus stopped")
            camera = self.app.__dict__.get("camera_window")
            if camera is None:
                raise FocusError("the camera is not live")
            frame = getattr(camera, "latest_frame", None)
            try:
                start = float(getattr(frame, "exposure_start_monotonic", math.nan))
            except (TypeError, ValueError):
                start = math.nan
            if frame is not None and math.isfinite(start) and (start > after) and all((frame is not taken for taken in frames)):
                frames.append(frame)
                continue
            if time.monotonic() >= deadline:
                raise FocusError(f'no camera frame begun after the focus move came within {deadline - after:.0f} s')
            time.sleep(0.01)
        images = [np.asarray(frame.raw, dtype=np.float64) for frame in frames]
        return focus_sharpness(sum(images) / len(images), self.roi)
    def _edge_reference(self, frame) -> EdgeResidualReference:
        background = getattr(frame, "background_raw", None)
        if background is None:
            raise ValueError("the frame carries no BG")
        key = (
            int(getattr(frame, "background_serial", 0) or 0), id(background),
            int(getattr(frame, "spatial_binning", 1) or 1), int(getattr(frame, "mean_filter_size", 1) or 1),
            tuple(np.shape(background)),
        )
        with self._edge_lock:
            cached = self._edge_cache
            if cached is not None and cached[0] == key:
                return cached[1]
            reference = EdgeResidualReference(background, key[2], key[3])
            self._edge_cache = (key, reference)
            return reference
    @staticmethod
    def _frame_difference(frame):
        shown = getattr(frame, "display_difference", None)
        return shown if shown is not None else getattr(frame, "difference", None)
    @staticmethod
    def _frame_drift(frame) -> float:
        try:
            drift = max(abs(float(frame.drift_dx)), abs(float(frame.drift_dy)))
        except (AttributeError, TypeError, ValueError):
            return 0.0
        return drift if math.isfinite(drift) else 0.0
    def _measure_super(self, stop_events=(), serial=None) -> float:
        after = max(self.frames_after, time.monotonic())
        frames = []
        camera = self.app.__dict__.get("camera_window")
        latest = getattr(camera, "latest_frame", None)
        try:
            exposure_s = float(latest.exposure_ms) / 1000.0
        except (AttributeError, TypeError, ValueError):
            exposure_s = 0.0
        if not math.isfinite(exposure_s):
            exposure_s = 0.0
        try:
            average = max(1, int(getattr(latest, "temporal_average_count", 1) or 1))
        except (TypeError, ValueError):
            average = 1
        deadline = time.monotonic() + FOCUS_FRAME_TIMEOUT_S + (2 * average + FOCUS_FRAMES_PER_POSITION + 1) * exposure_s
        while len(frames) < FOCUS_FRAMES_PER_POSITION:
            if self._cancelled(stop_events):
                raise FocusCancelled("auto focus stopped")
            camera = self.app.__dict__.get("camera_window")
            if camera is None:
                raise FocusError("the camera is not live")
            frame = getattr(camera, "latest_frame", None)
            if frame is not None:
                if getattr(frame, "background_serial", None) != serial:
                    raise FocusCancelled("the BG was recaptured")
                if getattr(frame, "background_mode", None) != "tracking" or self._frame_difference(frame) is None:
                    raise FocusCancelled("the difference display left Super")
            try:
                start = float(getattr(frame, "window_start_monotonic", math.nan))
            except (TypeError, ValueError):
                start = math.nan
            if frame is not None and math.isfinite(start) and (start > after) and all((frame is not taken for taken in frames)):
                frames.append(frame)
                continue
            if time.monotonic() >= deadline:
                raise FocusError(f'no difference frame begun after the focus move came within {deadline - after:.0f} s')
            time.sleep(0.01)
        images = [np.asarray(self._frame_difference(frame), dtype=np.float64) for frame in frames]
        try:
            value = edge_residual(sum(images) / len(images), self._edge_reference(frames[0]), max((self._frame_drift(frame) for frame in frames)), self.super_roi)
        except ValueError as error:
            raise FocusError(f"Super cannot judge the image: {error}") from error
        self.super_live_residual = value
        return value
    def _run(self, kind, reference_um, current_um, max_um, stop_events=(), recorder_attrs=()):
        def log(text):
            self.app.thread_log(text)
        result = error = None
        metric = self.running_metric
        try:
            if metric == "super":
                camera = self.app.__dict__.get("camera_window")
                roi = getattr(camera, "roi", None)
                self.super_roi = None if roi is None else dict(roi)
                serial = self.super_serial
                engine = SuperFocusSearch(
                    reference_um, current_um, max_um,
                    move=lambda target: self._move(target, stop_events, recorder_attrs, reference_um),
                    measure_residual=lambda: self._measure_super(stop_events, serial),
                    cancelled=lambda: self._cancelled(stop_events),
                    log=log,
                )
                result = engine.search() if kind == "search" else engine.check()
                return result, None
            camera = self.app.__dict__.get("camera_window")
            roi = getattr(camera, "roi", None)
            if roi is None:
                raise FocusError("draw a camera ROI first: the auto focus judges the focus inside it")
            self.roi = dict(roi)
            engine = FocusSearch(
                reference_um, current_um, max_um,
                move=lambda target: self._move(target, stop_events, recorder_attrs, reference_um),
                measure=lambda: self._measure(stop_events),
                cancelled=lambda: self._cancelled(stop_events),
                log=log,
            )
            result = engine.search() if kind == "search" else engine.check()
        except BaseException as caught:
            error = caught
        finally:
            with self.lock:
                self.running_kind = None
            self.app.post_ui(lambda: self._report(kind, result, error, recorder_attrs, metric))
        return result, error
    def _report(self, kind, result, error, recorder_attrs=(), metric="sharpness") -> None:
        if metric == "super":
            self._report_super(kind, result, error, recorder_attrs)
            return
        name = "Auto focus" if kind == "search" else "Keep in focus check"
        if result is not None:
            change = result.best_um - result.reference_um
            gain = (result.best_score / result.start_score - 1.0) * 100.0 if result.start_score > 0 else 0.0
            if kind == "search" and not result.peak_found:
                text = f"no clear peak within ±{FOCUS_RANGE_UM:g} µm; back at {result.best_um:g} µm"
            else:
                text = f"{('best' if kind == 'search' else 'checked')} at {result.best_um:g} µm ({change:+.1f} µm), sharpness {gain:+.0f} %" + (', at the window edge' if result.at_window_edge else '')
            self.status_var.set(f"Focus: {text}")
            self._log(f'{name}: {text} ({result.moves} moves; reference {result.reference_um:g} µm)', recorder_attrs)
            for attribute in recorder_attrs:
                self.app._scan_log(
                    attribute, "focus", kind=kind, position_um=result.best_um,
                    reference_um=result.reference_um, start_um=result.start_um, moves=result.moves,
                    peak_found=result.peak_found, at_window_edge=result.at_window_edge,
                )
        elif isinstance(error, FocusCancelled):
            self.status_var.set(f"Focus: {name.lower()} stopped")
            self._log(f"{name} stopped: {error}", recorder_attrs)
        else:
            self._fail(f"{name} stopped: {error}", recorder_attrs)
        self._update_controls()
    def _report_super(self, kind, result, error, recorder_attrs=()) -> None:
        name = "Super focus" if kind == "search" else "Super keep check"
        if result is not None:
            start = SuperFocusSearch.residual(result.start_score)
            best = SuperFocusSearch.residual(result.best_score)
            self.super_start_residual, self.super_live_residual = start, best
            self.super_best_residual = best
            offset = result.best_um - result.reference_um
            if kind == "search" and not result.peak_found:
                text = f"no clear edge-residual minimum within ±{FOCUS_RANGE_UM:g} µm of the BG's focus; back at {result.best_um:g} µm, edge residual {super_residual_text(best)}"
            else:
                text = (f"edge residual {super_residual_text(best)} (start {super_residual_text(start)}), "
                        f"focus {offset:+.1f} µm from the BG's focus"
                        + (", at the window edge" if result.at_window_edge else ""))
            self.status_var.set(f"Super: {text}")
            self._log(f"{name}: {text}; at {result.best_um:g} µm ({result.moves} moves; the BG's focus {result.reference_um:g} µm)", recorder_attrs)
            for attribute in recorder_attrs:
                self.app._scan_log(
                    attribute, "focus", kind=kind, metric="super", position_um=result.best_um,
                    reference_um=result.reference_um, start_um=result.start_um, moves=result.moves,
                    peak_found=result.peak_found, at_window_edge=result.at_window_edge,
                    edge_residual_start=round(start, 6), edge_residual=round(best, 6),
                )
        elif isinstance(error, FocusCancelled):
            why = str(error)
            self.status_var.set(f'Super: {name.lower()} stopped' + ('' if why in ('', 'auto focus stopped') else f' ({why})'))
            self._log(f"{name} stopped: {error}", recorder_attrs)
        else:
            self._fail(f"{name} stopped: {error}", recorder_attrs)
        self._update_controls()
    def _fail(self, text: str, recorder_attrs=()) -> None:
        self._set_keep(False)
        self.status_var.set(f"Focus: {short_status_error(text, 90)}; Keep in focus off")
        self._log(f"{text}; Keep in focus switched off", recorder_attrs)
        dialog = getattr(self.app, "_dialog_after_drain", None)
        if dialog is not None:
            dialog("showwarning", FOCUS_DIALOG_TITLE, f"{text}.\n\nKeep in focus is off.")
    def _set_keep(self, on: bool) -> None:
        self.keep_on = bool(on)
        try:
            self.keep_var.set(bool(on))
        except tk.TclError:
            pass
    def _update_controls(self) -> None:
        running = self.running_kind is not None
        idle_text = "Super focus" if self.super_on else "Auto focus"
        text = "Stop focus" if self.running_kind == "search" else idle_text
        role = button_role(text)
        for button in self.buttons:
            try:
                button.configure(text=text, style=button_role_style(role) if role else 'TButton', state='normal' if self.camera_ready or running else 'disabled')
            except tk.TclError:
                pass
        for tick in self.ticks:
            try:
                tick.configure(state="normal" if self.camera_ready else "disabled")
            except tk.TclError:
                pass
    def set_camera_ready(self, ready: bool) -> None:
        self.camera_ready = bool(ready)
        if not ready:
            self.cancel("the camera is not live", untick=True)
        self._update_controls()
    def refusal(self) -> str | None:
        if self.super_on:
            return self.super_refusal()
        motor = self._motor()
        if motor is None:
            return "the focus motor (Motor Control page) is not attached"
        reason = motor.focus_move_refusal()
        if reason:
            return reason
        camera = self.app.__dict__.get("camera_window")
        if camera is None or not self.app.__dict__.get("camera_connected"):
            return "the camera is not live"
        if getattr(camera, "latest_frame", None) is None:
            return "the camera has not produced a frame yet"
        if getattr(camera, "roi", None) is None:
            return "draw a camera ROI first: the auto focus judges the focus inside it"
        return None
    def _current(self):
        motor = self._motor()
        counts = int(motor.command_counts)
        return counts, counts / float(motor.abs_counts_per_um), float(motor.max_position_um)
    def _claim(self, kind: str) -> bool:
        with self.lock:
            if self.running_kind is not None:
                return False
            self.running_kind = kind
            self.running_metric = "super" if self.super_on else "sharpness"
            self.cancel_event.clear()
            return True
    def _confirm(self, what: str, reference_um: float, max_um: float) -> bool:
        low = max(0.0, reference_um - FOCUS_RANGE_UM)
        high = min(max_um, reference_um + FOCUS_RANGE_UM)
        if self.super_on:
            judged = f"the BG's focus {reference_um:g} µm), to make the device edges in the difference image as narrow as possible (inside the camera ROI, or the whole image when none is drawn)"
        else:
            judged = f"{reference_um:g} µm), scoring the sharpness inside the camera ROI"
        return bool(messagebox.askyesno(
            FOCUS_DIALOG_TITLE,
            f"{what} moves the focus motor in {FOCUS_STEP_UM:g} µm steps within "
            f"{low:g}–{high:g} µm (±{FOCUS_RANGE_UM:g} µm around {judged}.\n\nThe objective "
            "is close to the sample: confirm this range is safe and continue?",
            icon="warning", parent=self.app.root,
        ))
    def toggle_search(self) -> None:
        if self.running_kind == "search":
            self.cancel("Stop focus pressed")
            return
        reason = self.refusal()
        if reason is None and self.running_kind is not None:
            reason = "a Keep in focus check is running"
        if reason is None and self._scan_running():
            reason = "a scan is running (Keep in focus checks between its points)"
        if reason is None:
            reason = self.acquisition_busy()
        if reason:
            self.status_var.set(f"Focus: not started; {reason}")
            messagebox.showwarning(FOCUS_DIALOG_TITLE, f'Auto focus was not started: {reason}.', parent=self.app.root)
            return
        counts, current_um, max_um = self._current()
        if self.super_on:
            if self.keep_on and counts != self.expected_counts:
                self._fail("The focus motor was moved by another command since Keep in focus was ticked")
                return
            reference = self.super_reference_um
            reason = self._window_refusal(reference, current_um, max_um)
            if reason:
                self.status_var.set(f"Super: not started; {reason}")
                messagebox.showwarning(FOCUS_DIALOG_TITLE, f'Super focus was not started: {reason}.', parent=self.app.root)
                return
        elif self.reference_um is None or counts != self.expected_counts:
            if self.keep_on:
                self._fail("The focus motor was moved by another command since Keep in focus was ticked")
                return
            reference = current_um
        else:
            reference = self.reference_um
        if not self._confirm("Super focus" if self.super_on else "Auto focus", reference, max_um):
            return
        if not self._claim("search"):
            return
        self.reference_um, self.expected_counts = reference, counts
        if self.super_on:
            self.status_var.set(f"Super: searching for the narrowest edges around the BG's focus {reference:g} µm…")
        else:
            self.status_var.set(f"Focus: searching around {reference:g} µm…")
        self._update_controls()
        threading.Thread(target=self._run, args=('search', reference, current_um, max_um), name='auto-focus', daemon=True).start()
    def keep_changed(self) -> None:
        if not self.keep_var.get():
            self.keep_on = False
            if self.running_kind == "check":
                self.cancel("Keep in focus unticked")
            self.reference_um = None
            self.status_var.set("Focus: Keep in focus off")
            return
        reason = self.refusal()
        if reason is None and self.running_kind is not None:
            reason = "an auto focus search is running"
        if reason:
            self._set_keep(False)
            self.status_var.set(f"Focus: Keep in focus not started; {reason}")
            messagebox.showwarning(FOCUS_DIALOG_TITLE, f'Keep in focus was not started: {reason}.', parent=self.app.root)
            return
        counts, current_um, max_um = self._current()
        if self.super_on:
            reference = self.super_reference_um
            reason = self._window_refusal(reference, current_um, max_um)
            if reason:
                self._set_keep(False)
                self.status_var.set(f"Super: Keep in focus not started; {reason}")
                messagebox.showwarning(FOCUS_DIALOG_TITLE, f'Keep in focus was not started: {reason}.', parent=self.app.root)
                return
            if not self._confirm("Keep in focus (Super)", reference, max_um):
                self._set_keep(False)
                return
            self.reference_um, self.expected_counts = reference, counts
            self.keep_on = True
            self.last_check_monotonic = -math.inf
            self.status_var.set(f"Super: keeping the edges narrowest within ±{FOCUS_RANGE_UM:g} µm of the BG's focus {reference:g} µm")
            self._log(f"Keep in focus on (Super): the BG's focus {reference:g} µm, ±{FOCUS_RANGE_UM:g} µm, {FOCUS_STEP_UM:g} µm steps, lowest edge residual")
            return
        if not self._confirm("Keep in focus", current_um, max_um):
            self._set_keep(False)
            return
        self.reference_um, self.expected_counts = current_um, counts
        self.keep_on = True
        self.last_check_monotonic = -math.inf
        self.status_var.set(f"Focus: keeping within ±{FOCUS_RANGE_UM:g} µm of {current_um:g} µm")
        self._log(f'Keep in focus on: reference {current_um:g} µm, ±{FOCUS_RANGE_UM:g} µm, {FOCUS_STEP_UM:g} µm steps')
    def _check_ready_on_tk(self):
        if not self.keep_on or self.reference_um is None:
            return None
        motor = self._motor()
        if motor is not None and (motor.command_busy or motor.init_off_busy):
            return None
        reason = self.refusal()
        if reason:
            self._fail(f"Keep in focus stopped: {reason}")
            return None
        counts, current_um, max_um = self._current()
        if counts != self.expected_counts:
            self._fail("Keep in focus stopped: the focus motor was moved by another command")
            return None
        return self.reference_um, current_um, max_um
    def super_edges_widened(self) -> bool:
        live = self.__dict__.get("super_live_residual")
        if not self.super_on or not self.keep_on or live is None or not math.isfinite(live):
            return False
        best = self.__dict__.get("super_best_residual")
        floor = SUPER_AUTO_MIN_RESIDUAL if best is None else max(SUPER_AUTO_MIN_RESIDUAL, SUPER_AUTO_RATIO * best)
        return live > floor
    def idle_tick(self) -> None:
        root = self.app.__dict__.get("root")
        try:
            if root is not None and not self.app.__dict__.get("closing"):
                self.idle_after_id = root.after(FOCUS_IDLE_TICK_MS, self.idle_tick)
        except tk.TclError:
            self.idle_after_id = None
        since = time.monotonic() - self.last_check_monotonic
        widened = self.super_edges_widened() and since >= SUPER_AUTO_COOLDOWN_S
        if (
            not self.keep_on or self.running_kind is not None or self._scan_running()
            or self.acquisition_busy() or self.app.__dict__.get("closing")
            or (since < FOCUS_IDLE_INTERVAL_S and not widened)
        ):
            return
        ready = self._check_ready_on_tk()
        kind = "search" if widened else "check"
        if ready is None or not self._claim(kind):
            return
        self.last_check_monotonic = time.monotonic()
        if widened:
            self.status_var.set("Super: the edge lines widened; finding the focus…")
            self.app.thread_log(f'Super: edge residual {super_residual_text(self.super_live_residual)}; a Super focus search by itself (Keep in focus)')
        else:
            self.status_var.set("Focus: checking…")
        events = (_IdleStop(self),)
        threading.Thread(target=self._run, args=(kind, *ready, events), name='auto-focus-check', daemon=True).start()
    def cancel(self, reason: str, untick: bool = False) -> None:
        running = self.running_kind
        self.cancel_event.set()
        if untick and self.keep_on:
            self._set_keep(False)
            self.status_var.set(f"Focus: Keep in focus off; {reason}")
            self.app.thread_log(f"Keep in focus switched off: {reason}")
        if running is not None:
            self.app.thread_log(f"Auto focus stopped: {reason}")
    def motor_stopping(self, reason: str) -> None:
        self.cancel(reason, untick=True)
    def super_refusal(self) -> str | None:
        motor = self._motor()
        if motor is None:
            return "the focus motor (Motor Control page) is not attached"
        reason = motor.focus_move_refusal()
        if reason:
            return reason
        camera = self.app.__dict__.get("camera_window")
        if camera is None or not self.app.__dict__.get("camera_connected"):
            return "the camera is not live"
        frame = getattr(camera, "latest_frame", None)
        if frame is None:
            return "the camera has not produced a frame yet"
        if getattr(frame, "background_mode", None) != "tracking" or self._frame_difference(frame) is None:
            return "Super needs the drift-tracking difference on Camera Live"
        if self.super_reference_um is None:
            return f"the BG's focus is unknown ({self.super_reference_reason}): Recapture BG with the focus motor connected, homed and still"
        if getattr(frame, "background_serial", None) != self.super_serial:
            return "the BG is being recaptured"
        return None
    @staticmethod
    def _window_refusal(reference_um, current_um, max_um) -> str | None:
        if reference_um is None:
            return "the BG's focus is unknown: Recapture BG"
        try:
            FocusSearch(reference_um, current_um, max_um, None, None, None)
        except FocusError as error:
            return f"{error} (Super's window is ±{FOCUS_RANGE_UM:g} µm around the BG's focus {reference_um:g} µm; Recapture BG here to centre it on this position)"
        return None
    def set_super(self, on: bool, why: str = "", background_pending: bool = False) -> None:
        on = bool(on)
        if on == self.super_on:
            return
        was_keep = self.keep_on
        self.cancel(why or ("Super chosen" if on else "Super left"), untick=True)
        self.super_on = on
        self.reference_um = None
        self.super_live_residual = self.super_start_residual = None
        self.super_best_residual = None
        self.super_live_error = None
        self._live_last = -math.inf
        if on:
            self.app.thread_log('Super on: drift tracking plus the focus servo for the narrowest edges (inside the camera ROI, or the whole image when none is drawn)')
            self._take_super_reference("Super chosen", was_keep, background_pending)
        else:
            self.super_serial = self.super_reference_um = None
            self.super_reference_reason = "Super is off"
            self.status_var.set("Focus: Super off" + ("; Keep in focus off" if was_keep else ""))
            self.app.thread_log(f"Super off ({why or 'another mode chosen'})")
        self._update_controls()
    def note_capture_request(self) -> None:
        motor = self._motor()
        try:
            self.capture_request_counts = None if motor is None else int(motor.command_counts)
        except (AttributeError, TypeError, ValueError):
            self.capture_request_counts = None
        if self.super_on:
            self.cancel("Recapture BG", untick=True)
    def frame_arrived(self, frame) -> None:
        try:
            serial = int(getattr(frame, "background_serial", 0) or 0)
        except (TypeError, ValueError):
            serial = 0
        if serial and serial != self.seen_serial:
            self.seen_serial = serial
            self._background_captured(frame, serial)
        if self.super_on:
            self._schedule_live(frame)
    def _background_captured(self, frame, serial: int) -> None:
        um = counts = reason = None
        motor = self._motor()
        try:
            start = float(getattr(frame, "exposure_start_monotonic", math.nan))
        except (TypeError, ValueError):
            start = math.nan
        if motor is None:
            reason = "the focus motor was not attached"
        else:
            try:
                ready = bool(motor.controller.connected and motor.homed)
                busy = bool(motor.command_busy or motor.init_off_busy or motor.pending_target is not None)
                counts = int(motor.command_counts)
                scale = float(motor.abs_counts_per_um)
            except (AttributeError, TypeError, ValueError):
                ready, busy = False, False
            if not ready:
                reason = "the focus motor was not connected and homed"
            elif busy:
                reason = "the focus motor was busy with a command"
            elif self.running_kind is not None:
                reason = "a focus search or check was running"
            elif not math.isfinite(start):
                reason = "the BG frame's exposure time is not known"
            elif start <= self.frames_after:
                reason = "the focus motor was still settling after a focus move"
            elif self.capture_request_counts is not None and counts != self.capture_request_counts:
                reason = "the focus motor moved while the BG was being captured"
            elif self.unknown_counts is not None and counts == self.unknown_counts:
                reason = "the last focus move failed, so the position is not known"
            else:
                um = round(counts / scale, 4)
        self.capture_request_counts = None
        self.background_focus = (serial, um, counts if um is not None else None, reason)
        if self.super_on:
            self._take_super_reference("a new BG", self.keep_on)
    def _take_super_reference(self, why: str, was_keep: bool = False, pending: bool = False) -> None:
        self.cancel(why, untick=True)
        self.reference_um = None
        self.super_live_residual = self.super_start_residual = None
        self.super_best_residual = None
        self.super_live_error = None
        info = None if pending else self.background_focus
        keep_text = "; Keep in focus off (tick it again)" if was_keep else ""
        if info is not None and info[0] == self.seen_serial and info[1] is not None:
            self.super_serial, self.super_reference_um = info[0], info[1]
            self.super_reference_reason = None
            self.status_var.set(f"Super: reference {info[1]:g} µm (the BG's focus); Super focus searches ±{FOCUS_RANGE_UM:g} µm around it{keep_text}")
            self.app.thread_log(f"Super focus reference: {info[1]:g} µm, the focus motor's position when the BG was captured ({why})")
            return
        self.super_reference_um = None
        if info is None or info[0] != self.seen_serial:
            self.super_serial = None
            self.super_reference_reason = "no BG has been captured yet"
            self.status_var.set(f"Super: waiting for the BG capture{keep_text}")
            return
        self.super_serial = info[0]
        self.super_reference_reason = info[3]
        self.status_var.set(f"Super: the BG's focus is unknown ({info[3]}); Recapture BG with the motor homed and still{keep_text}")
        self.app.thread_log(f"Super: the BG's focus is unknown: {info[3]}")
    def _schedule_live(self, frame) -> None:
        if self._live_busy or self.running_kind is not None:
            return
        if time.monotonic() - self._live_last < SUPER_LIVE_INTERVAL_S:
            return
        if getattr(frame, 'background_mode', None) != 'tracking' or self._frame_difference(frame) is None or getattr(frame, 'background_raw', None) is None:
            return
        self._live_busy = True
        self._live_last = time.monotonic()
        threading.Thread(target=self._live_worker, args=(frame,), name="super-residual", daemon=True).start()
    def _live_worker(self, frame) -> None:
        value = error = None
        try:
            camera = self.app.__dict__.get("camera_window")
            roi = getattr(camera, "roi", None)
            value = edge_residual(self._frame_difference(frame), self._edge_reference(frame), self._frame_drift(frame), None if roi is None else dict(roi))
        except Exception as caught:
            error = caught
        serial = getattr(frame, "background_serial", None)
        self.app.post_ui(lambda: self._live_done(serial, value, error))
    def _live_done(self, serial, value, error) -> None:
        self._live_busy = False
        if not self.super_on or serial != self.seen_serial:
            return
        self.super_live_residual = value
        self.super_live_error = None if error is None else short_status_error(str(error), 80)
    def _focus_offset_text(self) -> str:
        if self.super_reference_um is None:
            return "BG focus unknown"
        position = self.position_for_row()
        if position == "":
            return "focus position unknown"
        return f"focus {float(position) - self.super_reference_um:+.1f} µm"
    def super_detail_text(self) -> str:
        if self.super_live_error:
            residual = f"edge residual not judged ({self.super_live_error})"
        else:
            residual = f"edge residual {super_residual_text(self.super_live_residual)}"
            if self.super_start_residual is not None:
                residual += f" (start {super_residual_text(self.super_start_residual)})"
        camera = self.app.__dict__.get("camera_window")
        area = "inside the ROI" if getattr(camera, "roi", None) is not None else "whole image (no ROI)"
        return f"Super: {residual}, {self._focus_offset_text()}; {area}"
    def super_overlay_text(self) -> str:
        text = f"Edge {super_residual_text(self.super_live_residual)}"
        if self.super_start_residual is not None:
            text += f" (start {super_residual_text(self.super_start_residual)})"
        return f"{text}   {self._focus_offset_text()}"
    def before_scan(self, recorder_attr: str | None = None) -> None:
        if recorder_attr and self.super_on:
            reference = self.super_reference_um
            if reference is not None:
                text = (f"Super focus reference: {reference:g} µm (the focus motor's position when the BG was "
                        f"captured), ±{FOCUS_RANGE_UM:g} µm, {FOCUS_STEP_UM:g} µm steps; Keep in focus "
                        + ("on" if self.keep_on else "off"))
            else:
                text = f"Super: the BG's focus is unknown ({self.super_reference_reason}); no Super focus move"
            self._log(text, (recorder_attr,))
            self.app._scan_log(recorder_attr, 'focus', kind='super_reference', metric='super', reference_um=reference, keep_in_focus=bool(self.keep_on))
        if self.running_kind is None:
            return
        self.cancel_event.set()
        deadline = time.monotonic() + FOCUS_STOP_WAIT_S
        while self.running_kind is not None:
            if time.monotonic() >= deadline:
                raise RuntimeError(f"the auto focus did not stop within {FOCUS_STOP_WAIT_S:g} s")
            time.sleep(0.02)
    def between_points(self, recorder_attr: str, stop_event) -> None:
        if not self.keep_on or stop_event.is_set() or self.app.__dict__.get("closing"):
            return
        if self.app.__dict__.get("magnet_scan_collecting") or self.app.__dict__.get("keithley_collecting"):
            return
        kind = "search" if self.super_edges_widened() else "check"
        if not self._claim(kind):
            return
        events = (stop_event,)
        attrs = (recorder_attr,)
        try:
            ready = self._call_on_tk(self._check_ready_on_tk, events)
        except BaseException as error:
            with self.lock:
                self.running_kind = None
            if not isinstance(error, FocusCancelled):
                message = f"Keep in focus stopped: {error}"
                self.app.post_ui(lambda: self._fail(message, attrs))
            return
        if ready is None:
            with self.lock:
                self.running_kind = None
            return
        self.app.post_ui(lambda: self.status_var.set('Super: the edge lines widened; finding the focus between points…' if kind == 'search' else 'Focus: checking between points…'))
        self._run(kind, *ready, events, attrs)
        self.last_check_monotonic = time.monotonic()
class _IdleStop:
    def __init__(self, manager: AutoFocusManager) -> None:
        self.manager = manager
    def is_set(self) -> bool:
        return self.manager._scan_running() or self.manager.acquisition_busy() is not None
