class NewmarkStageError(RuntimeError):
    pass
class NewmarkCommandNotAllowed(NewmarkStageError):
    pass
class NewmarkControllerError(NewmarkStageError):
    pass
class NewmarkRefused(NewmarkStageError):
    pass
class NewmarkLimitErrorLatched(NewmarkRefused):
    def __init__(self, mst):
        self.mst = mst
        super().__init__(f"a limit error is latched (MST {mst}: {newmark_describe_status(mst)}): the move was not "
                         "sent. To clear it, press Move stage or Start an Angle scan on the SHHV page, or Start a "
                         "sweep with the motor on the STFMR page, and answer Yes (CLR)")
class NewmarkDriverOff(NewmarkRefused):
    def __init__(self, eo):
        self.eo = eo
        super().__init__(f"the motor driver is off (EO={eo}): the position counter would advance without motion, so "
                         "the move was not sent. To switch it on, press Move stage or Start an Angle scan on the SHHV "
                         "page, or Start a sweep with the motor on the STFMR page, and answer Yes (EO=1)")
NEWMARK_FIXABLE_REFUSALS = (NewmarkLimitErrorLatched, NewmarkDriverOff)
def newmark_fix_prompt(error, page):
    if isinstance(error, NewmarkLimitErrorLatched):
        return (NewmarkLimitErrorLatched, 'CLR', f'{page} stage limit error', f'A limit error is latched on the stage (MST {error.mst}: {newmark_describe_status(error.mst)}). Clear it now (CLR)?')
    return (NewmarkDriverOff, "EO=1", f"{page} stage motor driver",
            f"The stage's motor driver is off (EO={error.eo}). Switch it on now (EO=1) and go on? "
            "The motor then holds the stage with its current.\n\n"
            "If the driver went off during a move, the angle shown may not be the stage's: "
            "answer No and check it first (Set stage 0° if needed).")
def newmark_fix_again_text(kind, error, command):
    again = f'The limit error is latched again (MST {error.mst}: {newmark_describe_status(error.mst)})' if kind is NewmarkLimitErrorLatched else f'The motor driver is off again (EO={error.eo})'
    return f"{again} right after {command} was read back, so nothing moved: check the stage"
def newmark_set_zero_question():
    return ("Call the stage's present position 0°?\n\n"
            f"The ±{NEWMARK_CABLE_LIMIT_DEG:g}° limit for the sample wires counts from the stage zero, so it "
            "moves with it: the wires must hang free here.\n\n"
            "The zero is kept across a USB reconnect but lost when the NSC-A1 is powered off.")
class NewmarkStageOwnership:
    def __init__(self):
        self.owner = None
        self.unconfirmed_stop = ""
    def claim(self, page, stage=None):
        if self.owner not in (None, page):
            raise RuntimeError(f"The motor is connected on the {self.owner} page: disconnect it there first.")
        self.owner = page
        if stage is not None:
            stage.share_stop_record(self)
    def release(self, page):
        if self.owner == page:
            self.owner = None
class NewmarkMotionError(NewmarkStageError):
    def __init__(self, message, stopped, px=None, notes=(), stop_ran=False):
        super().__init__(message)
        self.stopped, self.px, self.notes, self.stop_ran = stopped, px, list(notes), stop_ran
class NewmarkStopRequested(NewmarkStageError):
    def __init__(self, stopped, px=None, notes=(), steps_per_degree=None, before=False):
        self.stopped, self.px, self.notes, self.before = stopped, px, list(notes), before
        self.stop_ran = not before
        if before:
            text = "Stop was pressed before the stage move; nothing was sent"
        elif stopped:
            text = f"the stage move was stopped (Stop) at {newmark_angle_text(px, steps_per_degree)}"
        else:
            text = "Stop was pressed during a stage move, but the stage could not be confirmed stopped (STOP, then ABORT): CHECK THE STAGE (switch the NSC-A1's 24 V off if it still turns)"
        if self.notes:
            text += " (" + "; ".join(self.notes) + ")"
        super().__init__(text)
def newmark_check_allowed(command, steps_per_degree=None):
    if command in NEWMARK_READ_ONLY or command in NEWMARK_ACTIONS:
        return
    match = NEWMARK_NUMERIC.fullmatch(command)
    if not match:
        raise NewmarkCommandNotAllowed(f"{command!r} is not on the program's list of allowed NSC-A1 commands; it was not sent")
    name, value = (match.group(1), int(match.group(2))) if match.group(1) else (match.group(3), int(match.group(4)))
    top = round(NEWMARK_MAX_SPEED_DEG_S * (steps_per_degree or NEWMARK_FULL_STEPS_PER_DEG * NEWMARK_MAX_DRVMS))
    if name == "X":
        wire = round(NEWMARK_CABLE_LIMIT_DEG * steps_per_degree) if steps_per_degree else NEWMARK_PX_SAFE
        low, high = -wire, wire
    elif name == "PX=":
        low, high = -NEWMARK_PX_SAFE, NEWMARK_PX_SAFE
    elif name == "HSPD=":
        low, high = NEWMARK_MIN_LSPD + 1, top
    elif name == "LSPD=":
        low, high = NEWMARK_MIN_LSPD, top - 1
    else:
        low, high = 1, NEWMARK_MAX_ACC_MS
    if not low <= value <= high:
        raise NewmarkCommandNotAllowed(f"{command!r}: {value} is outside {low} - {high} for {name.rstrip('=')}; it was not sent")
def newmark_command_buffer(command):
    data = command.encode("ascii")
    if len(data) >= NEWMARK_BUFFER_SIZE:
        raise NewmarkCommandNotAllowed(f'{command!r} is {len(data)} bytes; commands must be shorter than {NEWMARK_BUFFER_SIZE}')
    return ctypes.create_string_buffer(data, NEWMARK_BUFFER_SIZE)
def newmark_clean_reply(raw):
    text = bytes(raw).split(b"\0", 1)[0].decode("ascii", "replace").strip("\r\n ")
    return re.sub(r"^#(?:SDE)?[0-9]{2}", "", text).strip("\r\n ")
def newmark_describe_status(mst):
    parts = ["moving" if mst & NEWMARK_MOVING else "not moving"]
    parts += [text for bit, text in NEWMARK_STATUS_BITS if mst >> bit & 1]
    parts += [f"bit {bit}" for bit in range(11, 32) if mst >> bit & 1]
    return ", ".join(parts)
def newmark_angle_text(px, steps_per_degree):
    if px is None:
        return "an unread position"
    if not steps_per_degree:
        return f"PX {px}"
    return f"{px / steps_per_degree:+.3f}°"
def newmark_looks_like_id(reply):
    return "SDE" in reply and not re.fullmatch(r"SDE[0-9]{2}", reply)
def newmark_stage_text(state):
    spd, px, mst = state.get("steps_per_degree"), state.get("px"), state.get("mst")
    text = f"Stage: {px / spd:+.3f}° ({spd} steps/°)" if spd else f"Stage: PX {px} (no steps/° scale)"
    if mst is not None:
        if mst & NEWMARK_MOVING:
            text += ", moving"
        if mst & NEWMARK_LIMIT_ERRORS:
            text += ", limit error latched"
        elif mst & NEWMARK_LIMIT_INPUTS:
            text += ", limit input on"
    return text
def newmark_declare_functions(dll):
    for name, argtypes in NEWMARK_SIGNATURES:
        function = getattr(dll, name, None)
        if function is None:
            if name == NEWMARK_FLUSH:
                continue
            raise NewmarkStageError(f"{name} is missing from {NEWMARK_DLL_NAME} (an old or a different DLL?)")
        function.argtypes = argtypes
        function.restype = ctypes.c_int
    return dll
def newmark_dll_folder():
    folders = [Path(__file__).resolve().parent]
    if getattr(sys, "frozen", False):
        folders.append(Path(sys.executable).resolve().parent)
    for folder in folders:
        if (folder / NEWMARK_DLL_NAME).is_file():
            return folder
    return None
NEWMARK_DLL_SOURCE = ('Arcus Technology\'s "USB 64-bit DLL v2.06" (arcus-technology.com, Support > Downloads), '
                      'with the Performax USB driver installed ("Performax USB Setup 4.01.3", Newmark\'s NSC-A1 page)')
def newmark_dll_bits(path):
    try:
        with open(path, "rb") as file:
            header = file.read(4096)
        if header[:2] != b"MZ":
            return None
        offset = int.from_bytes(header[0x3C:0x40], "little")
        if header[offset:offset + 4] != b"PE\0\0":
            return None
        machine = int.from_bytes(header[offset + 4:offset + 6], "little")
    except (OSError, ValueError):
        return None
    return {0x14C: 32, 0x8664: 64, 0xAA64: 64}.get(machine)
def newmark_check_dll_folder(folder):
    folder = Path(folder)
    if not (folder / NEWMARK_SIUSB_NAME).is_file():
        raise NewmarkStageError(f"{NEWMARK_DLL_NAME} is in {folder}, but {NEWMARK_SIUSB_NAME} is not: "
                                f"{NEWMARK_DLL_NAME} needs it. Copy {NEWMARK_SIUSB_NAME} from the same package "
                                f"({NEWMARK_DLL_SOURCE}) into that folder.")
    for name in (NEWMARK_DLL_NAME, NEWMARK_SIUSB_NAME):
        if newmark_dll_bits(folder / name) == 32:
            raise NewmarkStageError(f'{folder / name} is a 32-bit DLL; this Python is 64-bit, so both {NEWMARK_DLL_NAME} and {NEWMARK_SIUSB_NAME} must be the 64-bit ones ({NEWMARK_DLL_SOURCE}).')
def newmark_explain_load_error(path, error):
    code = getattr(error, "winerror", None)
    if code is None:
        found = re.search(r"\[WinError (\d+)\]", str(error))
        code = int(found.group(1)) if found else None
    if code == 193:
        return (f"Could not load {path} (WinError 193): it is not a 64-bit DLL. This Python is 64-bit, so "
                f"{NEWMARK_DLL_NAME} and {NEWMARK_SIUSB_NAME} must both be the 64-bit ones (Arcus \"USB 64-bit "
                "DLL v2.06\"), side by side in the program's folder.")
    if code == 126 or isinstance(error, FileNotFoundError):
        return (f"Could not load {path}: it, or a DLL it needs, was not found (Windows error 126). "
                f"{NEWMARK_DLL_NAME} needs {NEWMARK_SIUSB_NAME}, and Python does not search PATH for them: put "
                "both 64-bit DLLs together in the program's folder (beside Transport_all.py).")
    return f"Could not load {path}: {error}"
def newmark_load_performax():
    win_dll = getattr(ctypes, "WinDLL", None)
    if win_dll is None:
        raise NewmarkStageError(f'{NEWMARK_DLL_NAME} is a Windows DLL: the Newmark stage works on the lab PC (64-bit Python 3.11 on Windows)')
    bits = ctypes.sizeof(ctypes.c_void_p) * 8
    if bits != 64:
        raise NewmarkStageError(f'This is a {bits}-bit Python: the Newmark stage needs 64-bit Python 3.11 with the 64-bit DLLs')
    folder = newmark_dll_folder()
    path = NEWMARK_DLL_NAME
    if folder is not None:
        newmark_check_dll_folder(folder)
        if hasattr(os, "add_dll_directory"):
            _NEWMARK_DLL_DIRECTORIES.append(os.add_dll_directory(str(folder)))
        path = str(folder / NEWMARK_DLL_NAME)
        helper = folder / NEWMARK_SIUSB_NAME
        if helper.is_file():
            try:
                win_dll(str(helper))
            except OSError as error:
                raise NewmarkStageError(newmark_explain_load_error(helper, error)) from error
    try:
        dll = win_dll(path)
    except OSError as error:
        not_found = isinstance(error, FileNotFoundError) or getattr(error, 'winerror', None) == 126 or '[WinError 126]' in str(error)
        if folder is None and not_found:
            raise NewmarkStageError(
                f"{NEWMARK_DLL_NAME} was not found: it is not in the program's folder "
                f"({PROGRAM_DIRECTORY}), and Windows did not find it elsewhere. Copy the 64-bit "
                f"{NEWMARK_DLL_NAME} and {NEWMARK_SIUSB_NAME} into that folder. They come from "
                f"{NEWMARK_DLL_SOURCE}.") from error
        raise NewmarkStageError(newmark_explain_load_error(path, error)) from error
    return newmark_declare_functions(dll), path
class _EitherEvent:
    def __init__(self, *events):
        self.events = events
    def is_set(self):
        return any(event.is_set() for event in self.events)
class NewmarkNSCA1Controller:
    label = "Newmark NSC-A1"
    def __init__(self, logger, owner_scope="SHHV", loader=None, ownership=None):
        self.logger = logger
        self.owner_scope = str(owner_scope)
        self._loader = loader
        self._now, self._sleep = time.monotonic, time.sleep
        self.dll = None
        self.dll_path = ""
        self.handle = None
        self._thread_id = None
        self._no_flush_said = False
        self.ownership = None
        self._own_stop_record = NewmarkStageOwnership()
        if ownership is not None:
            self.share_stop_record(ownership)
        self._reset_session()
    def _reset_session(self):
        self.handle = None
        self._thread_id = None
        self.resource_name = ""
        self.identity = ""
        self.version = ""
        self.steps_per_degree = NEWMARK_STEPS_PER_DEGREE
        self.need_resync = False
        self.motion_may_run = False
        self.stop_finished = False
        self.stop_aborted = False
        self.in_move = False
        self.last_state = None
    @property
    def connected(self) -> bool:
        return self.handle is not None
    @property
    def motion_may_run(self) -> bool:
        return self._motion_may_run or bool(self.unconfirmed_stop)
    @motion_may_run.setter
    def motion_may_run(self, value):
        self._motion_may_run = bool(value)
    @property
    def stop_record(self) -> "NewmarkStageOwnership":
        return self.ownership if self.ownership is not None else self._own_stop_record
    @property
    def unconfirmed_stop(self) -> str:
        return self.stop_record.unconfirmed_stop
    def share_stop_record(self, ownership):
        if ownership is self.ownership:
            return
        own = self.stop_record.unconfirmed_stop
        self.ownership = ownership
        if own and not ownership.unconfirmed_stop:
            ownership.unconfirmed_stop = own
    def _note_unconfirmed_stop(self):
        when = datetime_module.datetime.now().astimezone().isoformat(timespec="seconds")
        self.stop_record.unconfirmed_stop = f'STOP and ABORT sent on the {self.owner_scope} page at {when}; not confirmed stopped'
    def _confirm_stopped(self, how):
        earlier = self.stop_record.unconfirmed_stop
        if earlier:
            self.stop_record.unconfirmed_stop = ""
            self.logger(f'{self.owner_scope} {self.label}: {how} confirmed the stage stopped; the earlier unconfirmed stop ({earlier}) is cleared')
    def _check_thread(self):
        if self._thread_id is not None and threading.get_ident() != self._thread_id:
            raise NewmarkStageError(f'{self.label}: a call from another thread was refused before it reached the DLL (its USB handles belong to the thread that connected)')
    def _function(self, name, optional=False):
        self._check_thread()
        function = getattr(self.dll, name, None)
        if function is None and not optional:
            raise NewmarkStageError(f"{name} is missing from {NEWMARK_DLL_NAME}")
        return function
    def _require_open(self):
        self._check_thread()
        if self.handle is None:
            raise NewmarkStageError(f"{self.label} is not connected")
    def _product_string(self, index, option):
        buffer = ctypes.create_string_buffer(NEWMARK_PRODUCT_STRING_SIZE)
        if not self._function("fnPerformaxComGetProductString")(index, buffer, option):
            return None
        return buffer.value.decode("ascii", "replace").strip()
    def devices(self):
        count = ctypes.c_uint32(0)
        if not self._function("fnPerformaxComGetNumDevices")(ctypes.pointer(count)):
            raise NewmarkStageError("fnPerformaxComGetNumDevices failed (is the Performax USB driver installed?)")
        return [(index, self._product_string(index, NEWMARK_SERIAL_OPTION), self._product_string(index, NEWMARK_DESCRIPTION_OPTION)) for index in range(count.value)]
    def _choose_device(self, serial):
        found = self.devices()
        if not found:
            raise NewmarkStageError(NEWMARK_NO_DEVICE_HELP)
        serials = ", ".join(repr(number) for _index, number, _text in found)
        if serial:
            matches = [(index, number) for index, number, _text in found if number == serial]
            if len(matches) != 1:
                raise NewmarkStageError(f'{len(matches)} Performax devices have the USB serial {serial!r} (found: {serials})')
            return matches[0]
        if len(found) > 1:
            raise NewmarkStageError(f"{len(found)} Performax devices are plugged in: type the NSC-A1's USB serial (one of {serials}) in place of auto")
        return found[0][0], found[0][1] or ""
    def _open(self, index):
        if not self._function("fnPerformaxComSetTimeouts")(NEWMARK_TIMEOUT_MS, NEWMARK_TIMEOUT_MS):
            raise NewmarkStageError("fnPerformaxComSetTimeouts failed")
        handle = ctypes.c_void_p()
        if not self._function("fnPerformaxComOpen")(index, ctypes.pointer(handle)) or not handle.value:
            raise NewmarkStageError(f'Could not open Performax device {index} (is QuickMotion or another program using it?)')
        self.handle = handle
        self._flush()
    def _flush(self):
        flush = self._function(NEWMARK_FLUSH, optional=True)
        if flush is None:
            if not self._no_flush_said:
                self.logger(f'{self.owner_scope} {self.label}: this {NEWMARK_DLL_NAME} has no {NEWMARK_FLUSH} (an older DLL)')
                self._no_flush_said = True
            return False
        try:
            return bool(flush(self.handle))
        except Exception:
            return False
    def _close_handle(self):
        if self.handle is None:
            return
        close = self._function("fnPerformaxComClose")
        try:
            close(self.handle)
        except Exception:
            pass
        self.handle = None
    def _transact(self, command):
        newmark_check_allowed(command, self.steps_per_degree)
        write = newmark_command_buffer(command)
        self._require_open()
        send_recv = self._function("fnPerformaxComSendRecv")
        read = ctypes.create_string_buffer(NEWMARK_BUFFER_SIZE)
        finished = False
        try:
            ok = send_recv(self.handle, write, NEWMARK_BUFFER_SIZE, NEWMARK_BUFFER_SIZE, read)
            finished = True
        finally:
            if not finished:
                self.need_resync = True
        if not ok:
            self.need_resync = True
            self._flush()
            raise NewmarkStageError(f"{command}: the USB transaction failed (it is not repeated)")
        reply = newmark_clean_reply(read.raw)
        if not reply:
            self.need_resync = True
            raise NewmarkStageError(f"{command}: an empty reply")
        if reply.startswith("?"):
            raise NewmarkControllerError(f"{command}: the controller answered {reply!r}")
        return reply
    def _resync(self):
        self._flush()
        identity = self._transact("ID")
        if not newmark_looks_like_id(identity):
            raise NewmarkStageError(f"after a flush ID answered {identity!r}: replies are out of step")
        version = self._transact("VER")
        if version == identity:
            raise NewmarkStageError(f"VER answered {version!r}, the ID reply: replies are still one behind")
        self.need_resync = False
    def query(self, command):
        if self.need_resync:
            self._resync()
        return self._transact(command)
    def number(self, command):
        reply = self.query(command)
        if not NEWMARK_INTEGER.fullmatch(reply):
            self.need_resync = True
            raise NewmarkStageError(f"{command} answered {reply!r}, not a number (a stale reply?)")
        return int(reply)
    def set_ok(self, command):
        reply = self.query(command)
        if reply != "OK":
            self.need_resync = True
            raise NewmarkStageError(f"{command} answered {reply!r}, not OK (a stale reply?)")
    def status(self):
        mst = self.number("MST")
        if mst < 0:
            self.need_resync = True
            raise NewmarkStageError(f"MST answered {mst} (a stale reply?)")
        return mst
    def _identify(self):
        try:
            identity = self._transact("ID")
        except NewmarkControllerError as error:
            raise NewmarkStageError(f"{error}: not an NSC-A1") from error
        if not newmark_looks_like_id(identity):
            raise NewmarkStageError(f"The device answered ID with {identity!r}, not an NSC-A1 (\"Ace-Series-SDE\"). "
                                    "If it is the NSC-A1, the reply may be a stale one: unplug and replug the USB "
                                    "cable and connect again.")
        version = self._transact("VER")
        if version == identity:
            raise NewmarkStageError(f'VER answered {version!r}, the ID reply: replies are out of step; unplug and replug the USB cable and connect again')
        return identity, version
    def connect(self, resource="auto"):
        if self.handle is not None:
            return self.identity
        requested = str(resource or "").strip()
        serial = "" if requested.lower() in ("", "auto") else requested
        self._thread_id = threading.get_ident()
        try:
            if self.dll is None:
                loader = self._loader or newmark_load_performax
                self.dll, self.dll_path = loader()
            index, chosen = self._choose_device(serial)
            self._open(index)
            identity, version = self._identify()
        except BaseException:
            self._close_handle()
            self._reset_session()
            raise
        self.resource_name, self.identity, self.version = chosen, identity, version
        self.logger(f"{self.owner_scope} {self.label} connected ({identity}, {version}): {self.scale_text()}")
        if self.unconfirmed_stop:
            self.logger(f'{self.owner_scope} {self.label}: its last stop was not confirmed ({self.unconfirmed_stop}), so it may still be turning: press Stop stage before any move (check the stage)')
        return identity
    def scale_text(self):
        return (f"{NEWMARK_STEPS_PER_DEGREE} steps/° ({NEWMARK_GEAR_RATIO}:1 x {NEWMARK_FULL_STEPS_PER_TURN} "
                f"full steps x microstep {NEWMARK_MICROSTEP} / 360; microstep {NEWMARK_MICROSTEP} from QuickMotion, "
                "fixed in the program)")
    def disconnect(self):
        if self.handle is None:
            self._reset_session()
            return
        self._check_thread()
        outcome, failure, aborted = None, None, False
        try:
            try:
                moving = bool(self.status() & NEWMARK_MOVING)
            except Exception:
                moving = self.motion_may_run
            if moving:
                outcome = self._stop_motion()
                aborted = self.stop_aborted
                if outcome[0]:
                    self._confirm_stopped("the STOP before closing")
        except Exception as error:
            failure = error
        finally:
            self._close_handle()
            spd = self.steps_per_degree
            self._reset_session()
        self.logger(f"{self.owner_scope} {self.label} disconnected")
        if outcome is not None and not outcome[0]:
            raise NewmarkStageError(f'{self.label} closed, but the stage could not be confirmed stopped (STOP, then ABORT): CHECK THE STAGE')
        if failure is not None:
            raise failure
        if outcome is not None:
            self.logger(f"{self.owner_scope} {self.label}: stopped before closing{(' (STOP, then ABORT)' if aborted else '')}, at {newmark_angle_text(outcome[1], spd)}")
    def read_state(self):
        self._require_open()
        mst = self.status()
        px = self.number("PX")
        spd = self.steps_per_degree
        state = {'px': px, 'mst': mst, 'moving': bool(mst & NEWMARK_MOVING), 'status_text': newmark_describe_status(mst), 'steps_per_degree': spd, 'angle_deg': px / spd if spd else None}
        self.last_state = dict(state, read_at=datetime_module.datetime.now().astimezone().isoformat(timespec='milliseconds'))
        return state
    def _check_ready(self):
        self._refuse_if_may_run()
        mst = self.status()
        if mst & NEWMARK_MOVING:
            raise NewmarkRefused(f"the stage is moving (MST {mst}: {newmark_describe_status(mst)}); stop it first")
        if mst & NEWMARK_LIMIT_INPUTS:
            raise NewmarkRefused(f"a limit input is on at rest (MST {mst}: {newmark_describe_status(mst)}), but the "
                                 "RM-5-110 has no limit switches: a polarity problem; fix the limit polarity in "
                                 "Newmark's QuickMotion")
        if mst & NEWMARK_LIMIT_ERRORS:
            raise NewmarkLimitErrorLatched(mst)
        eo = self.number("EO")
        if eo != 1:
            raise NewmarkDriverOff(eo)
        return mst
    def _refuse_if_may_run(self):
        if self.motion_may_run:
            raise NewmarkRefused(f"the {self.label}'s last stop was not confirmed, so it may still be turning: press Stop stage first (check the stage); nothing was sent")
    def check_ready(self):
        self._require_open()
        return self._check_ready()
    def clear_limit_error(self):
        self._require_open()
        mst = self.status()
        if mst & NEWMARK_MOVING:
            raise NewmarkRefused(f'the stage is moving (MST {mst}: {newmark_describe_status(mst)}); stop it first. CLR was not sent')
        if mst & NEWMARK_LIMIT_INPUTS:
            raise NewmarkRefused(f"a limit input is on at rest (MST {mst}: {newmark_describe_status(mst)}), but the "
                                 "RM-5-110 has no limit switches: a polarity problem; fix the limit polarity in "
                                 "Newmark's QuickMotion. CLR was not sent")
        if not mst & NEWMARK_LIMIT_ERRORS:
            self.logger(f"{self.owner_scope} {self.label}: no limit error is latched now (MST {mst}); CLR not sent")
            return mst
        self.set_ok("CLR")
        after = self.status()
        if after & NEWMARK_LIMIT_ERRORS:
            raise NewmarkStageError(f"CLR was sent, but MST read back still shows a limit error latched (MST {after}: "
                                    f"{newmark_describe_status(after)}); nothing moved. Check the stage (and its "
                                    "limit settings in QuickMotion)")
        self.logger(f"{self.owner_scope} {self.label}: limit error cleared (CLR; MST {mst} -> {after}, read back)")
        return after
    def enable_driver(self):
        self._require_open()
        mst = self.status()
        if mst & NEWMARK_MOVING:
            raise NewmarkRefused(f'the stage is moving (MST {mst}: {newmark_describe_status(mst)}); stop it first. EO=1 was not sent')
        eo = self.number("EO")
        if eo == 1:
            self.logger(f"{self.owner_scope} {self.label}: the motor driver is on now (EO=1); EO=1 not sent")
            return eo
        self.set_ok("EO=1")
        after = self.number("EO")
        if after != 1:
            raise NewmarkStageError(f'EO=1 was sent, but EO read back {after}, not 1: the motor driver is not on; nothing moved. Check the NSC-A1 (and QuickMotion)')
        self.logger(f"{self.owner_scope} {self.label}: motor driver switched on (EO=1; EO {eo} -> {after}, read back)")
        return after
    def _set_speeds(self, hspd, lspd, acc):
        if not NEWMARK_MIN_LSPD <= lspd < hspd:
            raise NewmarkCommandNotAllowed(f'LSPD {lspd} must be at least {NEWMARK_MIN_LSPD} and below HSPD {hspd}; nothing was sent')
        self.set_ok(f"HSPD={hspd}")
        self.set_ok(f"LSPD={lspd}")
        self.set_ok(f"ACC={acc}")
        hspd_read, lspd_read, acc_read = self.number("HSPD"), self.number("LSPD"), self.number("ACC")
        if (hspd_read, lspd_read) != (hspd, lspd):
            raise NewmarkRefused(f"the speeds read back HSPD {hspd_read}, LSPD {lspd_read} (set {hspd}, {lspd})")
        if acc_read <= 0:
            raise NewmarkRefused(f"ACC read back {acc_read} ms")
        return acc_read
    def move_to_deg(self, target_deg, stop_event, on_progress=None):
        self._require_open()
        target_deg = float(target_deg)
        if not math.isfinite(target_deg) or abs(target_deg) > NEWMARK_CABLE_LIMIT_DEG:
            raise NewmarkRefused(f'the stage target {target_deg:g}° is beyond ±{NEWMARK_CABLE_LIMIT_DEG:g}° of the zero (the sample wires); nothing moved')
        self._refuse_if_may_run()
        self.in_move = True
        try:
            if stop_event is not None and stop_event.is_set():
                raise NewmarkStopRequested(True, before=True)
            spd = self.steps_per_degree
            target = round(target_deg * spd)
            if abs(target) > round(NEWMARK_CABLE_LIMIT_DEG * spd) or abs(target) > NEWMARK_PX_SAFE:
                raise NewmarkRefused(f"the stage target PX {target} is beyond ±{NEWMARK_CABLE_LIMIT_DEG:g}° of the zero")
            hspd = round(NEWMARK_SPEED_DEG_S * spd)
            lspd = max(NEWMARK_MIN_LSPD, hspd // 10)
            self.set_ok("ABS")
            mode = self.number("MM")
            if mode != 0:
                raise NewmarkRefused(f"MM read back {mode}, not 0 (absolute)")
            acc = self._set_speeds(hspd, lspd, NEWMARK_ACC_MS)
            self._check_ready()
            start = self.number("PX")
            if start != target:
                if stop_event is not None and stop_event.is_set():
                    raise NewmarkStopRequested(True, before=True)
                timeout = 3 * (abs(target - start) / hspd + 2 * acc / 1000) + 5
                self.motion_may_run, self.stop_finished = True, False
                try:
                    self.set_ok(f"X{target}")
                except Exception as error:
                    stopped, px, notes = self._stop_motion()
                    sent = "STOP and ABORT sent" if self.stop_aborted else "STOP sent"
                    where = (f"{sent}; stopped at {newmark_angle_text(px, spd)}" if stopped else
                             "STOP and ABORT sent, but it could not be confirmed stopped: CHECK THE STAGE (switch "
                             "the NSC-A1's 24 V off if it still turns)")
                    raise NewmarkMotionError(f'{error}; the move may have started: {where}' + (f" ({'; '.join(notes)})" if notes else ''), stopped, px, notes, stop_ran=True) from error
                end, mst = self._wait_motion(target, timeout, stop_event, on_progress)
                if mst & NEWMARK_LIMIT_ERRORS:
                    raise NewmarkMotionError(f'the stage stopped with a limit error (MST {mst}: {newmark_describe_status(mst)}) at {newmark_angle_text(end, spd)}', True, end)
                if end != target:
                    raise NewmarkMotionError(
                        f"the stage ended at {newmark_angle_text(end, spd)} (PX {end}), not at the target "
                        f"{target_deg:+.3f}° (PX {target}, {end - target:+d} steps): steps lost, or the move was "
                        "cut short", True, end)
        finally:
            self.in_move = False
        return self.read_state()
    def _wait_motion(self, target, timeout_s, stop_event, on_progress):
        spd = self.steps_per_degree
        started = self._now()
        idle, idle_since, reason, asked = 0, None, None, False
        reported = -math.inf
        try:
            self._sleep(NEWMARK_POLL_S)
            while True:
                if stop_event is not None and stop_event.is_set():
                    asked = True
                    break
                mst = self.status()
                px = self.number("PX")
                now = self._now()
                if on_progress is not None and now - reported >= NEWMARK_PROGRESS_S:
                    reported = now
                    try:
                        on_progress(px, px / spd)
                    except Exception:
                        pass
                if mst & NEWMARK_MOVING:
                    idle, idle_since = 0, None
                else:
                    idle += 1
                    idle_since = now if idle_since is None else idle_since
                    if idle >= NEWMARK_IDLE_READS and (px == target or now - idle_since >= NEWMARK_SETTLE_S):
                        break
                if now - started > timeout_s:
                    reason = f"the stage move did not end within {timeout_s:.0f} s"
                    break
                self._sleep(NEWMARK_POLL_S)
        except Exception as error:
            reason = f"the stage move was cut off by an error ({error})"
        if asked:
            stopped, px, notes = self._stop_motion()
            raise NewmarkStopRequested(stopped, px, notes, spd)
        if reason is not None:
            stopped, px, notes = self._stop_motion()
            how = "STOP, then ABORT" if self.stop_aborted else "STOP"
            where = (f"stopped ({how}) at {newmark_angle_text(px, spd)}" if stopped else
                     "and it could not be confirmed stopped (STOP, then ABORT): CHECK THE STAGE (switch the "
                     "NSC-A1's 24 V off if it still turns)")
            raise NewmarkMotionError(f'{reason}, {where}' + (f" ({'; '.join(notes)})" if notes else ''), stopped, px, notes, stop_ran=True)
        self.motion_may_run = False
        return self.number("PX"), mst
    def _send_stop(self, command, notes):
        try:
            reply = self._transact(command)
            if reply != "OK":
                self.need_resync = True
                notes.append(f"{command} answered {reply!r}")
        except Exception as error:
            notes.append(f"{command}: {error}")
    def _wait_until_still(self, wait_s, notes):
        deadline = self._now() + wait_s
        idle, still_px = 0, None
        while True:
            try:
                if self.status() & NEWMARK_MOVING:
                    idle = 0
                else:
                    px = self.number("PX")
                    idle = idle + 1 if idle and px == still_px else 1
                    still_px = px
                    if idle >= NEWMARK_IDLE_READS:
                        break
            except Exception as error:
                idle = 0
                if str(error) not in notes:
                    notes.append(str(error))
            if self._now() >= deadline:
                return False, None
            self._sleep(NEWMARK_POLL_S)
        self.motion_may_run = False
        return True, still_px
    def _stop_motion(self, wait_s=NEWMARK_STOP_WAIT_S):
        self.stop_finished = self.stop_aborted = False
        notes = []
        self._send_stop("STOP", notes)
        stopped, px = self._wait_until_still(wait_s, notes)
        if not stopped:
            self.logger(f"{self.owner_scope} {self.label}: not stopped after STOP; ABORT")
            self.stop_aborted = True
            self._send_stop("ABORT", notes)
            stopped, px = self._wait_until_still(NEWMARK_ABORT_WAIT_S, notes)
            if stopped:
                notes.append("ABORT sent: STOP did not stop it")
        if not stopped:
            self._note_unconfirmed_stop()
        self.stop_finished = True
        return stopped, px, notes
    def stop(self):
        self._require_open()
        self.motion_may_run = True
        stopped, px, notes = self._stop_motion()
        if stopped:
            self._confirm_stopped("Stop stage")
        spd = self.steps_per_degree
        return {'stopped': stopped, 'px': px, 'notes': notes, 'steps_per_degree': spd, 'angle_deg': px / spd if px is not None and spd else None, 'aborted': self.stop_aborted}
    def set_zero(self):
        self._require_open()
        mst = self.status()
        if mst & NEWMARK_MOVING:
            raise NewmarkRefused("the stage is moving; stop it first")
        before = self.number("PX")
        self.set_ok("PX=0")
        now = self.number("PX")
        if now != 0:
            raise NewmarkStageError(f"PX read back {now} after PX=0")
        self.logger(f'{self.owner_scope} {self.label}: zero set here (was {newmark_angle_text(before, self.steps_per_degree)}, PX {before})')
        return before
def rte_scan_plan(mode, start, end, step, loops=1, round_trip=True, max_current_a=STFMR_KEPCO_MAX_CURRENT_A, supply='KEPCO', values=None):
    if mode not in ('Field', 'Current', 'Angle', *SWITCH_MODES):
        raise ValueError('SHHV supports only Field, Current and Angle scans')
    nodes = tuple(values) if values is not None else tuple(ppms_scan_axis(float(start), float(end), float(step)))
    if mode == SWITCH_SCAN_MODE:
        limit_ma = K6221_MAX_ABS_CURRENT_A * 1e3
        outside = [v for v in nodes if abs(v) > limit_ma]
        if outside:
            raise ValueError(f'6221 pulse currents must stay within +/-{limit_ma:g} mA; {outside[0]:g} mA is outside')
    if mode == SWITCH2_SCAN_MODE:
        outside = [v for v in nodes if abs(v) > AVTECH_MAX_AMPLITUDE_V]
        if outside:
            raise ValueError(f'Avtech pulse amplitudes must stay within +/-{AVTECH_MAX_AMPLITUDE_V:g} V; {outside[0]:g} V is outside')
    if mode == 'Field' and any(abs(v) > max_current_a for v in nodes):
        raise ValueError(f'{supply} sweep current must stay within +/-{max_current_a:g} A')
    if mode == 'Angle':
        outside = [v for v in nodes if abs(v) > NEWMARK_CABLE_LIMIT_DEG]
        if outside:
            raise ValueError(f'Stage angles must stay within +/-{NEWMARK_CABLE_LIMIT_DEG:g}° of the stage zero (the sample wires); {outside[0]:g}° is outside')
    loops_value = float(loops)
    if not math.isfinite(loops_value) or not loops_value.is_integer() or not 1 <= loops_value <= 10000:
        raise ValueError('Loops must be an integer from 1 to 10000')
    if round_trip:
        nodes += nodes[-2::-1]
    if len(nodes) * int(loops_value) > 100000:
        raise ValueError('SHHV scans are limited to 100000 points')
    return tuple(((loop, point, value) for loop in range(1, int(loops_value) + 1) for point, value in enumerate(nodes, 1)))
def rte_outer_plan(mode, start, end, step, max_current_a=STFMR_KEPCO_MAX_CURRENT_A, supply='KEPCO'):
    inner = {'Angle+Current': 'Current'}.get(mode)
    if inner is None:
        raise ValueError('Only Angle+Current scans have a Start / End / Step outer loop')
    label = RTE_OUTER_ROWS[mode]['label'].rstrip(':').replace('KEPCO', supply)
    try:
        return tuple((value for _loop, _point, value in rte_scan_plan(inner, start, end, step, 1, False, max_current_a, supply)))
    except ValueError as error:
        raise ValueError(f'{label}: {error}') from error
def rte_outer_list_plan(text):
    label = RTE_OUTER_ROWS['Angle+Field']['label'].rstrip(':')
    parts = [part for part in re.split(r'[,;\s]+', str(text).strip()) if part]
    if not parts:
        raise ValueError(f'{label}: type the fields in G in the order to scan, e.g. 500, 100, 300')
    if len(parts) > RTE_OUTER_LIST_MAX:
        raise ValueError(f'{label}: at most {RTE_OUTER_LIST_MAX} fields ({len(parts)} typed)')
    values = []
    for part in parts:
        try:
            value = float(part)
        except ValueError:
            raise ValueError(f'{label}: "{part}" is not a number') from None
        if not math.isfinite(value):
            raise ValueError(f'{label}: "{part}" is not a finite number')
        if abs(value) > RTE_OUTER_FIELD_MAX_G:
            raise ValueError(f'{label}: fields must stay within +/-{RTE_OUTER_FIELD_MAX_G:g} G ({RTE_OUTER_FIELD_MAX_G:g} Oe); {value:g} G is outside')
        values.append(value + 0.0)
    return tuple(values)
def rte_outer_angle_list_plan(text):
    label = RTE_OUTER_ROWS[FIELD_ANGLE_SCAN_MODE]['label'].rstrip(':')
    parts = [part for part in re.split(r'[,;\s]+', str(text).strip()) if part]
    if not parts:
        raise ValueError(f'{label}: type the stage angles in degrees in the order to scan, e.g. 0, 45, 90')
    if len(parts) > RTE_OUTER_LIST_MAX:
        raise ValueError(f'{label}: at most {RTE_OUTER_LIST_MAX} angles ({len(parts)} typed)')
    values = []
    for part in parts:
        try:
            value = float(part)
        except ValueError:
            raise ValueError(f'{label}: "{part}" is not a number') from None
        if not math.isfinite(value):
            raise ValueError(f'{label}: "{part}" is not a finite number')
        if abs(value) > NEWMARK_CABLE_LIMIT_DEG:
            raise ValueError(f'{label}: stage angles must stay within +/-{NEWMARK_CABLE_LIMIT_DEG:g}° of the stage zero (the sample wires); {value:g}° is outside')
        values.append(value + 0.0)
    return tuple(values)
def rte_outer_angles_text(values, limit=12):
    shown = ', '.join(f'{value:+g}' for value in values[:limit])
    return f"{shown}{', ...' if len(values) > limit else ''}°"
def rte_pulse_list(text, box='Pulses mA', what='pulse currents', unit='mA', example='-10, -5, 0, 5, 10'):
    parts = [part for part in re.split(r'[,;\s]+', str(text).strip()) if part]
    if not parts:
        raise ValueError(f'{box}: type the {what} in {unit} in the order to scan, e.g. {example}')
    if len(parts) > RTE_OUTER_LIST_MAX:
        raise ValueError(f'{box}: at most {RTE_OUTER_LIST_MAX} {what} ({len(parts)} typed)')
    values = []
    for part in parts:
        try:
            value = float(part)
        except ValueError:
            raise ValueError(f'{box}: "{part}" is not a number') from None
        if not math.isfinite(value):
            raise ValueError(f'{box}: "{part}" is not a finite number')
        values.append(value + 0.0)
    return tuple(values)
def rte_pulse_axis(mode):
    return 'avtech' if mode == SWITCH2_SCAN_MODE else 'pulse'
def rte_outer_values_text(values, limit=12, unit='G'):
    shown = ', '.join(f'{value:+g}' for value in values[:limit])
    return f"{shown}{', ...' if len(values) > limit else ''} {unit}"
def rte_outer_step_of(row):
    if row.get('scan_mode') in RTE_FIELD_LIST_MODES and 'outer_field_index' in row:
        value, index = row.get('outer_target_field_g'), row.get('outer_field_index')
        if isinstance(value, (int, float)) and math.isfinite(value):
            return float(value), f'#{index} {value:+g} G'
        return (float(index) if isinstance(index, (int, float)) else 0.0), f'step {index}'
    if 'outer_angle_index' in row:
        value, index = row.get('stage_target_deg'), row.get('outer_angle_index')
        if isinstance(value, (int, float)) and math.isfinite(value):
            return float(value), f'#{index} {value:+g}°'
        return (float(index) if isinstance(index, (int, float)) else 0.0), f'step {index}'
    if 'outer_current_index' in row:
        value, unit, form = row.get('6221_current_rms_ma'), 'mA', 'g'
    else:
        return None
    if not isinstance(value, (int, float)) or not math.isfinite(value):
        index = row.get('outer_current_index')
        return (float(index) if isinstance(index, (int, float)) else 0.0), f'step {index}'
    return float(value), f'{value:{form}} {unit}'
RTE_STATUS_WIDEST_EXAMPLE = "Stopped; outputs held unless OFF was requested; stage stopped at -359.999°"
def rte_outputs_text(results, check=True, supply='KEPCO'):
    names = ("6221", supply)
    if results:
        six = results.get("6221", "")
        avtech = {"Avtech": results["avtech"]} if "avtech" in results else {}
        results = {**avtech, "6221": six if six == "zeroed" else "zero FAILED", supply: results.get("kepco", "")}
        names = (*avtech, *names)
    return scan_end_outputs_text(results, names, check=check, together=f"{supply} and 6221" if len(names) == 2 else f"Avtech, {supply} and 6221")
RTE_FAILED_STATUS_CHARS = 64
def rte_unconfirmed_outputs(results, supply='KEPCO') -> list[str]:
    if not results:
        return ["6221", supply]
    failed = [] if results.get("6221") == "zeroed" else ["6221"]
    if results.get("avtech", "zeroed") not in ("zeroed", "not connected"):
        failed.insert(0, "Avtech")
    if results.get("kepco") not in ("zeroed", "not connected"):
        failed.append(supply)
    return failed
def rte_failed_status_text(error, results, supply='KEPCO') -> str:
    failed = rte_unconfirmed_outputs(results, supply)
    if not failed:
        return f"Failed: {short_status_error(error, 100)}"
    tail = '; outputs not confirmed zeroed' if not results else f"; {' and '.join(failed)} zero FAILED"
    text = short_status_error(error, RTE_FAILED_STATUS_CHARS - len("Failed: ") - len(tail)).rstrip(";")
    return f"Failed: {text}{tail}"
RTE_RED_BUTTON_COLORS = RED_BUTTON_COLORS
RTE_MAGNET_CHOICES = (MAGNET_SUPPLY_KEPCO, LAKESHORE_MAGNET_MODELS['643']['label'])
RTE_SCAN_NOTES = {
    'Field': 'Field: KEPCO A; readback: signed LS475 G',
    'Current': 'Field: KEPCO A; readback: signed LS475 G',
    'Angle': 'Angle: Stage °; field: KEPCO current A',
    'Angle+Field': 'Angle+Field: Stage °; outer: field G',
    'Angle+Current': 'Angle+Current: Stage °; outer: 6221 mA',
    'Field+Angle': 'Field+Angle: KEPCO A; outer: stage °',
    SWITCH_SCAN_MODE: 'Switch: 6221 pulse mA; outer: field G',
    SWITCH2_SCAN_MODE: 'Switch2: Avtech pulse V; outer: field G',
}
def rte_angle_not_started_text(reason, mode='Angle'):
    text = short_status_error(reason, 44 - (len(mode) - len('Angle'))).rstrip('; ') if isinstance(reason, BaseException) else reason
    return f'{mode} scan not started: {text}'
class RTEPanel(PPMSPanel):
    ppms_page_name = 'SHHV'
    rte_scan_modes = RTE_SCAN_MODES
    rte_default_scan_mode = RTE_DEFAULT_SCAN_MODE
    def _rte_harmonic_orders(self, key):
        return self._ppms_harmonic_orders(key)
    def _ppms_direct_transport_settings(self):
        if not self.ppms_instrument_controllers['6221'].connected:
            raise ValueError('Please connect the 6221')
        active, zurich = self._ppms_selected_lockins()
        addresses = [self.ppms_instrument_controllers[k].resource_name for k in active]
        if len(set(addresses)) != len(addresses):
            raise ValueError('The SR830 addresses must differ')
        return validate_ppms_transport_scan_settings(
            self.ppms_transport_current_var.get(), self.ppms_transport_frequency_var.get(),
            self.ppms_transport_compliance_var.get(), self._ppms_harmonic_value('830_a'),
            self._ppms_harmonic_value('830_b'), active, allow_no_lockins=zurich,
            harmonic_c=self._ppms_harmonic_value('830_c'))
    def _ppms_apply_selected_harmonic(self, key):
        self._refresh_ppms2_plot_layout()
        if self.ppms_environment_busy or self.ppms_field_scan_running:
            return
        if self.ppms_instrument_controllers[key].connected:
            harmonic = self._rte_harmonic_orders(key)[0]
            self.ppms_field_scan_stop_event.clear()
            self._rte_submit(lambda: self._rte_set_harmonic(key, harmonic))
    def _rte_set_harmonic(self, key, harmonic):
        self._rte_wait(0)
        self._ppms_write_sr830_checked(key, f'HARM {harmonic}')
        if self._ppms_query_numbers(key, 'HARM?', 1)[0] != harmonic:
            raise RuntimeError(f'{key} harmonic readback mismatch: requested {harmonic}')
        state = getattr(self, 'ppms_sr830_range_states', {}).get(key)
        if state is not None:
            state.low_range_count = state.range_cooldown = 0
    def _rte_harmonic_passes(self, settings):
        return self._ppms_harmonic_passes(settings)
    def __init__(self, parent, tab):
        self.rte_closed = False
        self.rte_controllers = {
            'kepco': STFMRKepco4886Controller(self.thread_log),
            'gauss': STFMRGauss475Controller(self.thread_log),
            'newmark': NewmarkNSCA1Controller(self.thread_log),
            'lakeshore': LakeShoreMagnetSupplyController(self.thread_log, '643', owner_scope=self.ppms_page_name),
            'avtech': AvtechPulserController(self.thread_log),
        }
        self.rte_magnet_choice = MAGNET_SUPPLY_KEPCO
        self.rte_magnet_rate_a_s = LAKESHORE_DEFAULT_RATE_A_S
        self.rte_stage_stop_event = threading.Event()
        self.rte_stage_where = ''
        self.rte_stage_prompt_open = False
        super().__init__(parent, tab)
        self.zurich_controller.mfli_server_candidates = SUPER_ZURICH_MFLI_SERVERS
        self.zurich_resource.set(zurich_mfli_label(SUPER_ZURICH_MFLI_DEVICE))
        for controller in self.ppms_instrument_controllers.values():
            controller.owner_scope = self.ppms_page_name
        self.rte_controllers['gauss'].owner_scope = self.ppms_page_name
        self.rte_controllers['kepco'].owner_scope = self.ppms_page_name
        self.rte_controllers['newmark'].owner_scope = self.ppms_page_name
        self.rte_controllers['avtech'].owner_scope = self.ppms_page_name
        self.rte_controllers['newmark'].share_stop_record(self._newmark_stage_ownership())
        self.ppms_plot_frame.configure(text=f'{self.ppms_page_name}: X, Y, phase vs measured field / excitation current / sample angle / pulse current')
        self.ppms_transport_current_var.set(f'{RTE_TRANSPORT_CURRENT_RMS_MA:g}')
        self.ppms_transport_frequency_var.set(f'{RTE_TRANSPORT_FREQUENCY_HZ:g}')
        self.ppms_transport_compliance_var.set(f'{RTE_TRANSPORT_COMPLIANCE_V:g}')
        self.zurich_expected_frequency = RTE_TRANSPORT_FREQUENCY_HZ
        self.ppms_transport_harmonic_a_var.set('2')
        self.ppms_transport_harmonic_b_var.set('2')
        self.ppms_transport_harmonic_c_var.set('3')
        self.zurich_harmonic.set(RTE_ZURICH_DEFAULT_HARMONICS)
        for key, measured in (('830_a', True), ('830_b', False), ('830_c', False), ('zurich', False)):
            self.ppms_lockin_selection[key].set(measured)
        self.ppms_acquisition_time_var.set(f'{RTE_ACQUISITION_S:g}')
        self.rte_acquisition_default_shown = f'{RTE_ACQUISITION_S:g}'
        self.ppms_simple_mode.set(self.rte_default_scan_mode)
        self._rte_mode_changed()
        self.rte_magnet_choice_var.set(RTE_MAGNET_CHOICES[1])
        self._rte_magnet_choice_changed()
        frame = ttk.LabelFrame(self.ppms_plot_frame, text=SWITCH_TIME_ROW_TITLE, padding=2)
        frame.rowconfigure(0, weight=1)
        self.rte_time_canvases = {}
        for column, channel in enumerate(('x', 'y')):
            frame.columnconfigure(column, weight=1, uniform='rte_time')
            canvas = tk.Canvas(frame, height=PPMS_PLOT_ROW_MIN_HEIGHT_PX, width=300, background='white', highlightthickness=0)
            canvas.ppms_compact_plot = True
            canvas.grid(row=0, column=column, sticky='nsew')
            canvas.bind('<Configure>', lambda event: self._request_plot_redraw())
            self.rte_time_canvases[channel] = canvas
        self.rte_time_frame, self.rte_time_row_on = frame, False
        self._refresh_ppms2_plot_layout()
        self._update_ppms_control_ui()
    def _rte_time_row_shown(self):
        return self.__dict__.get('ppms_plot_axis') in ('pulse', 'avtech')
    def _rte_plot_axis_changed(self):
        if self.__dict__.get('rte_time_frame') is not None and self._rte_time_row_shown() != self.__dict__.get('rte_time_row_on', False):
            self._refresh_ppms2_plot_layout()
        else:
            self._redraw_ppms_transport_plot()
    def _rte_live_time_tick(self):
        self.rte_live_time_after = None
        if self.rte_closed or self.closing or not self.ppms_field_scan_running or self.__dict__.get('ppms_active_scan_mode') not in SWITCH_MODES:
            return
        live, trace = self.__dict__.get('rte_switch_live'), self.__dict__.get('ppms_sample_trace')
        drawn = (live or {}).get('index'), len(trace or ())
        if live and trace and drawn != self.__dict__.get('rte_live_drawn'):
            self.rte_live_drawn = drawn
            self._redraw_switch_time_plot()
        self.rte_live_time_after = self.root.after(int(SWITCH_LIVE_REDRAW_S * 1000), self._rte_live_time_tick)
    def _switch_time_order(self):
        orders = self._ppms2_measured_orders()
        for order in PPMS_HARMONIC_ORDERS:
            if orders.get(order):
                return order, orders[order]
        return None, []
    def _refresh_ppms2_plot_layout(self):
        super()._refresh_ppms2_plot_layout()
        frame = self.__dict__.get('rte_time_frame')
        if frame is None:
            return
        self.rte_time_row_on = self._rte_time_row_shown()
        if not self.rte_time_row_on:
            frame.grid_remove()
            return
        orders = self._ppms2_measured_orders()
        frames = self.__dict__.get('ppms_harmonic_plot_frames') or {}
        for (harmonic, channel), harmonic_frame in frames.items():
            if channel == 'theta':
                harmonic_frame.grid_remove()
        self.ppms_plot_frame.columnconfigure(2, weight=0, minsize=0, uniform='')
        row = sum(1 for order in PPMS_HARMONIC_ORDERS if orders.get(order))
        order, meters = self._switch_time_order()
        names = ', '.join(PPMS_SR830_LABELS.get(key, 'Zurich') for key in meters)
        frame.configure(text=SWITCH_TIME_ROW_TITLE + (f' — {PPMS_HARMONIC_LABELS[order]}, {names}' if meters else ''))
        frame.grid(row=row, column=0, columnspan=3, sticky='nsew')
        self.ppms_plot_frame.rowconfigure(row, weight=1, uniform='ppms_plot_rows')
        self._redraw_switch_time_plot()
    def _redraw_switch_time_plot(self):
        canvases = self.__dict__.get('rte_time_canvases') or {}
        if not canvases or not self._rte_time_row_shown():
            return
        order, meters = self._switch_time_order()
        traces = list(self.__dict__.get('rte_switch_traces') or [])
        live, readings = self.__dict__.get('rte_switch_live'), list(self.__dict__.get('ppms_sample_trace') or ())
        if live and readings and self.__dict__.get('ppms_field_scan_running'):
            started = self.ppms_field_scan_started_at
            traces.append(dict(live, times=[at - started for at, _values in readings], values=[values for _at, values in readings]))
        wanted = []
        for meter in meters:
            address = None if meter == 'zurich' else self._ppms2_meter_address(meter)
            if address is not None:
                wanted.append((meter, str(address)))
        total = sum(len(entry['times']) for entry in traces) * max(1, len(wanted))
        step = max(1, math.ceil(total / SWITCH_TRACE_MOST_DRAWN))
        for channel, canvas in canvases.items():
            series, colors = {}, {}
            for meter, address in wanted:
                key = f'sr830_{address}_{channel}_v'
                label = PPMS_SR830_LABELS.get(meter, meter)
                for entry in traces:
                    if str(entry['harmonics'].get(address)) != str(order):
                        continue
                    points = [(at, values[key]) for at, values in zip(entry['times'], entry['values']) if key in values][::step]
                    if points:
                        name = f"{label} #{entry['index']}"
                        series[name] = points
                        colors[name] = PPMS_METER_COLORS.get(meter, '#666666')
            self._draw_nonlocal_series(canvas, series, 'Time (s)', f'{channel.upper()} voltage', 'Waiting for scan data',
                                       markers=True, marker_radius=1.5, auto_voltage_unit=True, show_legend=False,
                                       series_colors=colors)
    def __getattr__(self, name):
        if name.startswith('rte_'):
            raise AttributeError(name)
        return super().__getattr__(name)
    def _initialize_ppms_state(self):
        super()._initialize_ppms_state()
        for key in PPMS_SR830_KEYS:
            setattr(self, PPMS_SR830_HARMONIC_ATTRS[key], tk.StringVar(value=str(self._ppms_harmonic_var(key).get())))
        self.ppms_executor.shutdown(wait=False)
        self.ppms_executor = ThreadPoolExecutor(max_workers=1, thread_name_prefix='rte-control')
    def _set_zurich_busy(self, busy):
        super()._set_zurich_busy(busy)
        if self.ppms_environment_busy or self.rte_closed:
            for widget in (*self.zurich_entries, self.zurich_reference_combo, self.zurich_harmonic_combo, self.zurich_select, self.zurich_connect_button, self.zurich_disconnect_button):
                widget.configure(state='disabled')
    def _poll_ppms2_zurich(self):
        if self.rte_closed or self.closing:
            return
        if self.ppms_environment_busy:
            self.zurich_after_id = self.root.after(1000, self._poll_ppms2_zurich)
        else:
            super()._poll_ppms2_zurich()
    def connect_ppms2_zurich(self, *, apply_only=False):
        if not self.ppms_environment_busy and not self.rte_closed:
            super().connect_ppms2_zurich(apply_only=apply_only)
